router.post('/_bw/getorgsfromsqlserver', function (request, response) {
    try {
        console.log('In POST./_windows/getorgsfromsqlserver()xcx1.');
        var authentication = {};
        sequelize.authenticate()
            .then(function () {
                try {
                    sequelize.query("SELECT * FROM Org", { type: sequelize.QueryTypes.SELECT })
                        .then(function (orgs) {
                            // We don't need spread here, since only the results will be returned for select queries
                            //var results = 'THIS IS SAMPLE DATA FROM THE DATABASE. Orgs: ' + JSON.stringify(orgs);

                            authentication = {
                                connectionStatus: 'connected',
                                results: JSON.stringify(orgs)
                            }

                            response.send(authentication);
                        })

                } catch (e) {
                    console.log('EXCEPTION XCX334-2');
                }
            })
            .catch(function (e) {
                authentication = {
                    connectionStatus: 'not connected',
                    exception: e.parent
                }
                response.send(authentication);
            })
            .finally(function () {
                console.log(JSON.stringify(authentication));
                //response.send(authentication);
            });

        //var bwTenantId = request.body.bwTenantId;
        //var bwWorkflowAppId = request.body.bwWorkflowAppId;
        //var bwSelectedCurrencySymbol = request.body.bwSelectedCurrencySymbol;
        //var modified = new Date(); // Converted from getCreatedTimestamp(); 2-6-2022

    } catch (e) {
        var msg = 'Error in POST /getorgsfromsqlserver:' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.getorgsfromsqlserver()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);
        //
        //var result = { message: msg };
        response.send(msg);
    }
});

router.post('/_bw/getorgrolesfromsqlserver', function (request, response) {
    try {
        console.log('In POST./_windows/getorgrolesfromsqlserver()xcx1.');
        var authentication = {};
        sequelize.authenticate()
            .then(function () {
                try {
                    var sql = "";
                    sql += "SELECT ur.OrgId, ur.RoleId, r.RoleName, ur.UserId, cu.FirstName, cu.LastName, cu.UserEMail ";
                    sql += "FROM UserRole ur ";
                    sql += "INNER JOIN Role r on ur.RoleId = r.RoleId ";
                    sql += "INNER JOIN CARUser cu on ur.UserId = cu.UserId ";
                    sql += "WHERE r.IsWorkflowRole = 1 ";
                    sql += "AND ur.RoleId != 'ADMIN' ";
                    sequelize.query(sql, { type: sequelize.QueryTypes.SELECT })
                        .then(function (orgRolesParticipants) {
                            // We don't need spread here, since only the results will be returned for select queries
                            //var results = 'THIS IS SAMPLE DATA FROM THE DATABASE. Orgs: ' + JSON.stringify(orgs);

                            authentication = {
                                connectionStatus: 'connected',
                                results: JSON.stringify(orgRolesParticipants)
                            }

                            response.send(authentication);
                        })

                } catch (e) {
                    console.log('EXCEPTION XCX334-2');
                }
            })
            .catch(function (e) {
                authentication = {
                    connectionStatus: 'not connected',
                    exception: e.parent
                }
                response.send(authentication);
            })
            .finally(function () {
                console.log(JSON.stringify(authentication));
                //response.send(authentication);
            });

        //var bwTenantId = request.body.bwTenantId;
        //var bwWorkflowAppId = request.body.bwWorkflowAppId;
        //var bwSelectedCurrencySymbol = request.body.bwSelectedCurrencySymbol;
        //var modified = new Date(); // Converted from getCreatedTimestamp(); 2-6-2022

    } catch (e) {
        var msg = 'Error in POST /getorgrolesfromsqlserver:' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.getorgrolesfromsqlserver()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);
        //
        //var result = { message: msg };
        response.send(msg);
    }
});



