function deleteTheForm(bwTenantId, bwWorkflowAppId, bwFormId, theLastOne) {
    return new Promise(function (resolve, reject) {
        try {
            console.log('In deleteTheForm(). THIS IS THE ONLY PLACE WHERE WE SHOULD BE DELETING FORMS. bwTenantId: ' + bwTenantId + ', bwWorkflowAppId: ' + bwWorkflowAppId + ', bwFormId: ' + bwFormId);
            var BwBudgetRequest = mongoose.model('BwBudgetRequest');
            var BwForm = mongoose.model('BwForm');

            BwBudgetRequest.find({
                bwWorkflowAppId: bwWorkflowAppId, bwFormId: bwFormId
            }, function (brfError, brfResult) {
                if (brfError) {
                    var msg = 'Error in deleteTheForm.BwBudgetRequest.find(): ' + brfError;
                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.deleteforms()';
                    var errorCode = null;
                    //var message = msg;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);
                    //
                    //var results = { message: msg };
                    //console.log(msg);
                    var result = {
                        message: msg
                    }
                    reject(result);
                } else {
                    console.log('In deleteTheForm. brfResult.length: ' + brfResult.length + ', bwFormId: ' + bwFormId);
                    if (brfResult.length == 0) {
                        //
                        // If the form isn't being used for any requests, then we are allowed to delete it.
                        //
                        BwForm.remove({
                            bwWorkflowAppId: bwWorkflowAppId, bwFormId: bwFormId, bwFormActive: false
                        }, function (error, mod) { // This prevents active workflows from being deleted. No user feedback presently, it just doesn't delete active ones.
                            //BwForm.remove({ bwTenantId: form.bwTenantId, bwWorkflowAppId: form.bwWorkflowAppId, bwFormId: form.bwFormId }, function (error, result) { // This prevents active workflows from being deleted. No user feedback presently, it just doesn't delete active ones.
                            if (!error) {
                                console.log('In deleteTheForm. SUCCESS for bwFormId: ' + bwFormId + '. mod: ' + JSON.stringify(mod));

                                var result = {
                                    message: 'SUCCESS',
                                    TheLastOne: theLastOne,
                                    mod: mod
                                }
                                resolve(result);
                            } else {
                                // Exception section:
                                var msg = 'Error in deleteTheForm.remove.deleteforms(): ' + error;
                                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.post./_bw/deletependingemails()';
                                var errorCode = null;
                                //var message = msg;
                                WriteToErrorLog(threatLevel, source, errorCode, msg);
                                ////
                                //response.send('Error in post./_bw/deleteforms: ' + error);
                                var result = {
                                    message: msg
                                }
                                reject(result);
                            }
                        });
                    } else {
                        var msg = 'There are ' + brfResult.length + ' requests which use this form. Therefore this form cannot be deleted at this time.';
                        console.log(msg);
                        var result = {
                            message: msg
                        }
                        resolve(result);
                    }
                }
            });
        } catch (e) {
            var msg = 'Exception in POST addOrUpdateParticipantOrgRole(): ' + e.message + ', ' + e.stack;
            // Exception section:
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js.addOrUpdateParticipantOrgRole()';
            var errorCode = null;
            var message = msg;
            WriteToErrorLog(threatLevel, source, errorCode, message);
            console.log(msg);
            reject(msg);
        }
    });
}

