                                //    console.log('Exception calling removeParticipantOrgRole() for ' + roleId + ', result: ' + result + ': ' + e.message + ', ' + e.stack);
                                //}
                                console.log('Performed REMOVE. ' + result.message); // for ' + roleId + ', ' + orgId);


                                if (result.TheLastOne == true) {
                                    var result = {
                                        DivisionIndex: divisionIndex,
                                        GroupIndex: groupIndex,
                                        EntityIndex: entityIndex,
                                        LocationIndex: locationIndex
                                    }
                                    resolve(result);
                                }
