function removeParticipantOrgRole(request, bwTenantId, bwWorkflowAppId, bwParticipantId, bwParticipantFriendlyName, bwParticipantEmail, roleId, orgId, modifiedById, modifiedByFriendlyName, modifiedByEmail, theLastOne) {
    return new Promise(function (resolve, reject) {
        try {
            console.log('In removeParticipantOrgRole(). THIS IS THE ONLY PLACE WHERE WE SHOULD BE REMOVING PARTICIPANT ORG ROLES. roleId: ' + roleId + ', orgId: ' + orgId);
            var BwWorkflowUserRole = mongoose.model('BwWorkflowUserRole');
            var dtNow = new Date();
            //BwWorkflowUserRole.find({ bwTenantId: bwTenantId, bwWorkflowAppId: bwWorkflowAppId, bwParticipantId: bwParticipantId, RoleId: roleId, OrgId: orgId, Active: true }, function (urfError, urfResult) {
            BwWorkflowUserRole.find({
                bwWorkflowAppId: bwWorkflowAppId, bwParticipantId: bwParticipantId, RoleId: roleId, OrgId: orgId
            }, function (urfError, urfResult) {
                if (urfError) {
                    // Exception section:
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.removeParticipantOrgRole()';
                    var errorCode = null;
                    var message = urfError;
                    WriteToErrorLog(threatLevel, source, errorCode, message);
                    response.send('Error in LOOKING UP ROLE PARTICIPANTS IN removeParticipantOrgRole(). roleId: ' + roleId + ', orgId: ' + orgId + ': ' + urfError);
                    reject(message);
                } else {
                    console.log('LOOKING UP ROLE PARTICIPANTS IN removeParticipantOrgRole(). urfResult.length: ' + urfResult.length);
                    if (urfResult.length > 1) {
                        reject('RETURNED TO MANY RECORDS FROM BwWorkflowUserRole.find in start.js.removeParticipantOrgRole().');
                    } else if (urfResult.length == 1) {
                        // We found an entry, so do a DELETE.
                        var bwWorkflowUserRoleId = urfResult[0].bwWorkflowUserRoleId;
                        BwWorkflowUserRole.remove({
                            bwWorkflowUserRoleId: bwWorkflowUserRoleId
                        }, function (trError, trResult) {
                            if (!trError) {

                                // Save to BwOrganizationEvents.
                                var guid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                                    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                                    return v.toString(16);
                                });

                                var description = modifiedByFriendlyName + ' (' + modifiedByEmail + ') has successfully deleted the ' + roleId + ' role in Organization "' + orgId + '.';

                                var now = new Date();
                                var ipAddressString = request.headers['x-forwarded-for'] || request.connection.remoteAddress || request.socket.remoteAddress || request.connection.socket.remoteAddress;
                                var bwOrganizationEvents = new BwOrganizationEvents({
                                    bwOrganizationEventsId: guid,
                                    bwWorkflowAppId: bwWorkflowAppId,
                                    Description: description,
                                    //Description_Html: '',
                                    //Description_Json: xx,
                                    EventType: 'ROLE_MEMBERSHIP_CHANGES',
                                    EventSubType: 'REMOVE_ORGANIZATION_ROLE',
                                    Created: now,
                                    CreatedById: modifiedById,
                                    CreatedByEmail: modifiedByEmail,
                                    CreatedByFriendlyName: modifiedByFriendlyName,
                                    CreatedByIpAddress: ipAddressString
                                });
                                bwOrganizationEvents.save(function (oesError) {
                                    try {
                                        if (oesError) {

                                            var msg = 'Error in removeParticipantOrgRole():3-3: ' + oesError;
                                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                            var source = 'start.js.removeParticipantOrgRole()';
                                            var errorCode = null;
                                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                                            var result = {
                                                message: msg,
                                                TheLastOne: theLastOne
                                            }
                                            resolve(result);

                                        } else {

                                            console.log('SUCCESSFULLY DELETED BwWorkflowUserRole: ' + trResult);
                                            var result = {
                                                message: 'SUCCESSFULLY DELETED BwWorkflowUserRole for ' + roleId + ', ' + orgId + '.',
                                                TheLastOne: theLastOne
                                            }
                                            resolve(result);

                                        }
                                    } catch (e) {

                                        var msg = 'Exception in POST removeParticipantOrgRole:4-4: ' + e.message + ', ' + e.stack;
                                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                        var source = 'start.js.POST.removeParticipantOrgRole()';
                                        var errorCode = null;
                                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                                        var result = {
                                            message: msg,
                                            TheLastOne: theLastOne
                                        }
                                        resolve(result);

                                    }
                                });

                            } else {
                                var msg = 'Error DELETE the post /UserRole: ' + trError;
                                // Exception section:
                                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.post.UserRole()';
                                var errorCode = null;
                                var message = msg;
                                WriteToErrorLog(threatLevel, source, errorCode, message);
                                //
                                //var results = { message: msg };
                                reject(msg);
                            }
                        });
                    } else {
                        var result = {
                            message: 'UNEXPECTED RESPONSE DELETING BwWorkflowUserRole for ' + roleId + ', ' + orgId + '. Unexpected response in removeParticipantOrgRole(): This means that the JSON has roles which are no longer in the BwWorkflowUserRole table. WE NEED TO CLEAN UP THE JSON HERE. urfResult: ' + JSON.stringify(urfResult),
                            TheLastOne: theLastOne
                        }
                        resolve(result);
                    }
                }
            });
        } catch (e) {
            var msg = 'Exception in POST removeParticipantOrgRole(): ' + e.message + ', ' + e.stack;
            // Exception section:
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js.removeParticipantOrgRole()';
            var errorCode = null;
            var message = msg;
            WriteToErrorLog(threatLevel, source, errorCode, message);
            console.log(msg);
            reject(msg);
        }
    });
}

