                var source = 'start.js.getParticipantsForRaciRoles3()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg);

                var result = {
                    status: 'ERROR',
                    message: msg
                }
                reject(result);

