function writeTimerLogEntry(details) {
    var bwTimerLogEntryId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
    var created = new Date(); // Converted from getCreatedTimestamp(); 2-6-2022
    var BwTimerLog = mongoose.model('BwTimerLog');
    var bwTimerLog = new BwTimerLog(
        {
            bwTimerLogEntryId: bwTimerLogEntryId,
            bwTimerLogEntryDetails: details,
            bwTimerLogEntryCreatedTimestamp: created
        });
    bwTimerLog.save(function (error) {
        if (!error) {
            bwTimerLog.save();
            //response.end('Created');
            //console.log('Saved new timer log entry:' + details);
            console.log('timerlog: ' + details);
        } else {
            console.log('Error saving new timer log entry:' + details);
            console.log(error);
            // Exception section:
            var threatLevel = 'guarded'; // severe, high, elevated, guarded, low.
            var source = 'start.js.writeTimerLogEntry()';
            var errorCode = null;
            var message = error;
            WriteToErrorLog(threatLevel, source, errorCode, message);
        }
    });
}



