router.get('/odata/Roles/:bwWorkflowAppId/:participantId', function (request, response) {
    try {
        var bwWorkflowAppId = request.params.bwWorkflowAppId;
        var participantId = request.params.participantId;
        //console.log('');
        console.log('In /odata/Roles/:bwWorkflowAppId/:participantId. bwWorkflowAppId: ' + bwWorkflowAppId + ', participantId: ' + participantId);
        // GET THE CURRENT WORKFLOW AND PARSE OUT THE ROLES! Then iterate through them to display!.
        BwWorkflow.find({
            bwWorkflowAppId: bwWorkflowAppId, bwWorkflowActive: true
        }, function (wfError, wfResult) {
            try {
                if (!wfError) {

                    if (wfResult.length == 0) {
                        console.log('/odata/Roles/:bwWorkflowAppId/:participantId>>>>>>>>RETURNING :1:');
                        var msg = 'Partially successful response from the web service /odata/Roles/:bwWorkflowAppId/:participantId. RETURNING NO WORKFLOW';
                        var data = {
                            message: msg,
                            workflow: null, //jsonWorkflow4,
                            userRoles: ''
                        };
                        response.send(data);
                    } else {
                        var workflow = JSON.parse(wfResult[0].bwWorkflowJson); //.Workflow
                        var msg = 'Successful response from the web service /odata/Roles/:bwWorkflowAppId/:participantId:2:.';
                        var data = {
                            message: msg,
                            workflow: workflow, //result,
                            userRoles: '',
                            orgRoles: ''
                        };
                        BwWorkflowUserRole.find({
                            bwWorkflowAppId: bwWorkflowAppId, bwParticipantId: participantId
                        }, function (error, result) {
                            try {
                                if (!error) {

                                    data.userRoles = result;

                                    BwOrgRoles.find({
                                        bwWorkflowAppId: bwWorkflowAppId, bwOrgRolesActive: true
                                    }, function (error, result) {
                                        if (!error) {
                                            try {

                                                var orgRoles = JSON.parse(result[0].bwOrgRolesJson);
                                                data.orgRoles = orgRoles;

                                                response.send(data);

                                            } catch (e) {

                                                // Exception section:
                                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                                var source = 'Exception in GET start.js.get./odata/Roles/:' + bwWorkflowAppId + '/:' + participantId + ' from BwOrgRoles.find():';
                                                var errorCode = null;
                                                var message = e.message + ', ' + e.stack + ', result: ' + JSON.stringify(result);
                                                WriteToErrorLog(threatLevel, source, errorCode, message);
                                                //
                                                response.send('Exception in GET /start.js.get./odata/Roles/:' + bwWorkflowAppId + '/:' + participantId + ' from BwOrgRoles.find(): ' + e.message + ', ' + e.stack);
                                            }
                                        } else {
                                            // Exception section:
                                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                            var source = 'start.js.GET.WorkflowConfiguration()  /:isActive:1';
                                            var errorCode = null;
                                            var message = error;
                                            WriteToErrorLog(threatLevel, source, errorCode, message);
                                            //
                                            response.send('Error in start.js.get./odata/Roles/:bwWorkflowAppId/:participantId  /:isActive:1:' + error);
                                        }
                                    });



                                } else {
                                    // Exception section:
                                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.get./odata/Roles/:bwWorkflowAppId/:participantId';
                                    var errorCode = null;
                                    var message = error;
                                    WriteToErrorLog(threatLevel, source, errorCode, message);
                                    //
                                    response.send('Error in get./odata/Roles/:bwWorkflowAppId/:participantId: ' + error);
                                }
                            } catch (e) {
                                console.log('Exception in GET /odata/Roles/:bwWorkflowAppId/:participantId()1:. ' + e.message + ', ' + e.stack);
                                response.send('Exception in GET /odata/Roles/:bwWorkflowAppId/:participantId()1:. ' + e.message + ', ' + e.stack);
                            }
                        });
                    }
                } else {
                    // Exception section:
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.GET./odata/Roles/:bwWorkflowAppId/:participantId:1';
                    var errorCode = null;
                    var message = wfError;
                    WriteToErrorLog(threatLevel, source, errorCode, message);
                    //
                    response.send('Error in GET /odata/Roles/:bwWorkflowAppId/:participantId:1:' + wfError);
                }
            } catch (e) {
                console.log('Exception in GET /odata/Roles/:bwWorkflowAppId/:participantId(). ' + e.message + ', ' + e.stack);
                response.send('Exception in GET /odata/Roles/:bwWorkflowAppId/:participantId(). ' + e.message + ', ' + e.stack);
            }
        });
    } catch (e) {
        var msg = 'Error in GET /odata/Roles/:bwWorkflowAppId/:participantId ' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'budgetnetwebservice.js.GET./odata/Roles/:bwWorkflowAppId/:participantId';
        var errorCode = null;
        var message = msg;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        //var results = { message: msg };
        response.send(msg);
    }
});



