router.post('/odata/publishworkflow2', function (request, response) {
    try {

        var ip = request.headers['x-forwarded-for'] ||
            request.connection.remoteAddress ||
            request.socket.remoteAddress ||
            (request.connection.socket ? request.connection.socket.remoteAddress : null
            );
        var ips = [];
        for (var x = 0; x < ip.split(',').length; x++) {
            if (ip.split(',')[x].trim() == '127.0.0.1') {
                // do nothing
            } else {
                // add to array
                ips.push(ip.split(',')[x].trim());
            }
        }

        console.log('In /odata/publishworkflow2: Attempt to save workflow from (' + ips + ')');

        var bwWorkflowAppId = request.body.bwWorkflowAppId;
        var bwRequestTypeId = request.body.bwRequestTypeId;
        var ModifiedByFriendlyName = request.body.ModifiedByFriendlyName;
        var ModifiedById = request.body.ModifiedById;
        var ModifiedByEmail = request.body.ModifiedByEmail;
        var bwWorkflowJson = request.body.bwWorkflowJson;

        var timestamp = new Date();

        if (!bwWorkflowAppId) {

            var msg = 'Error inpublishworkflow2() updating the workflow: bwWorkflowAppId: ' + bwWorkflowAppId;
            // Exception section:
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js.post.publishworkflow2():1:';
            var errorCode = null;
            var message = msg;
            WriteToErrorLog(threatLevel, source, errorCode, message);
            //
            //var results = { message: msg };
            console.log(msg);
            response.send(msg);

        } else {

            //
            // CHECK IF A WORKFLOW EXISTS FOR THE bwRequestTypeId. If not, save, otherwise, update the existing one. There can only be one workflow for a bwWorkflowAppId and bwRequestTypeId. 1-4-2022
            //

            BwWorkflow.find({
                bwWorkflowAppId: bwWorkflowAppId, bwRequestTypeId: bwRequestTypeId
            }, function (wfError, wfResult) {
                try {
                    if (!wfError) {

                        if (wfResult.length == 0) {
                            //
                            // Save.
                            //
                            var bwWorkflowId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                                var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                                return v.toString(16);
                            });
                            var bwWorkflow = new BwWorkflow(
                                {
                                    bwWorkflowId: bwWorkflowId,
                                    bwWorkflowAppId: bwWorkflowAppId,
                                    bwRequestTypeId: bwRequestTypeId,
                                    CreatedBy: ModifiedByFriendlyName,
                                    CreatedById: ModifiedById,
                                    CreatedByEmail: ModifiedByEmail,
                                    bwWorkflowJson: bwWorkflowJson,
                                    bwWorkflowActive: true,
                                    isActive: true
                                });
                            bwWorkflow.save(function (wsError, wsMod) {
                                try {
                                    if (!wsError) {
                                        console.log('WORKFLOW SAVED. mod: ' + JSON.stringify(wsMod));
                                        response.send('SUCCESS');
                                    } else {
                                        console.log('WORKFLOW NOT SAVED . ERROR: ' + JSON.stringify(wsError) + ', mod: ' + JSON.stringify(wsMod));
                                        response.send('Error in save publishworkflow2(): ' + JSON.stringify(wsError) + ', mod: ' + JSON.stringify(wsMod));
                                    }
                                } catch (e) {
                                    // Exception section:
                                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.POST.publishworkflow2() save xcx3254';
                                    var errorCode = null;
                                    var message = e.message;
                                    WriteToErrorLog(threatLevel, source, errorCode, message);
                                    //
                                    response.send('Exception in POST publishworkflow2 xcx00334-1: ' + e.message);
                                }
                            }); f

                        } else {
                            //
                            // Update.
                            //
                            BwWorkflow.update({
                                bwWorkflowAppId: bwWorkflowAppId, bwRequestTypeId: bwRequestTypeId
                            }, {
                                Modified: timestamp, ModifiedByFriendlyName: ModifiedByFriendlyName, ModifiedById: ModifiedById, ModifiedByEmail: ModifiedByEmail, bwWorkflowJson: bwWorkflowJson, bwWorkflowActive: true, isActive: true
                            }, {
                            }, function (wuError, wuMod) {
                                try {
                                    if (!wuError) {

                                        //console.log('');
                                        console.log('SUCCESS in publishworkflow2.BwWorkflow.update(). bwWorkflowAppId: ' + bwWorkflowAppId + ', bwRequestTypeId: ' + bwRequestTypeId + ', wuMod: ' + JSON.stringify(wuMod));
                                        //console.log('');

                                        var modifiedCount = 0;
                                        if (wuMod.hasOwnProperty('modifiedCount')) {
                                            modifiedCount = wuMod.modifiedCount;
                                        } else if (wuMod.hasOwnProperty('nModified')) {
                                            modifiedCount = wuMod.nModified;
                                        }

                                        //if (!wuMod.hasOwnProperty('modifiedCount')) {
                                        //    throw new Error('xcx123423423-6 Object missing property "modifiedCount".');
                                        //}

                                        if (modifiedCount == 1) {
                                            response.send('SUCCESS');
                                        } else {
                                            response.send('Unexpected mod value on update: ' + JSON.stringify(wuMod));
                                        }

                                    } else {
                                        var msg = 'Error updating the post /publishworkflow2: ' + wuError;
                                        // Exception section:
                                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                        var source = 'start.js.post.publishworkflow2():1:';
                                        var errorCode = null;
                                        var message = msg;
                                        WriteToErrorLog(threatLevel, source, errorCode, message);
                                        //
                                        //var results = { message: msg };
                                        response.send(msg);

                                    }
                                } catch (e) {
                                    // Exception section:
                                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.POST.publishworkflow2() update xcx3254-2';
                                    var errorCode = null;
                                    var message = e.message;
                                    WriteToErrorLog(threatLevel, source, errorCode, message);
                                    //
                                    response.send('Exception in POST publishworkflow2 xcx00334-2: ' + e.message);
                                }
                            });
                        }

                    } else {
                        // Exception section:
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.publishworkflow2:1';
                        var errorCode = null;
                        var message = wfError;
                        WriteToErrorLog(threatLevel, source, errorCode, message);
                        //
                        response.send('Error in publishworkflow2:1:' + wfError);
                    }

                } catch (e) {

                    var msg = 'Exception in POST publishworkflow2 xcx00334 - 3: ' + e.message + ', ' + e.stack;
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.POST.publishworkflow2() xcx3254-3';
                    var errorCode = null;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                    response.send('Exception in POST publishworkflow2 xcx00334-3: ' + e.message + ', ' + e.stack);

                }
            });

        }
    } catch (e) {
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.publishworkflow2()';
        var errorCode = null;
        var message = e.message;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        response.send('Exception in POST publishworkflow2 xcx00334-4: ' + e.message);
    }
});



