router.post('/odata/publishofflineform', function (request, response) {
    try {

        var ip = request.headers['x-forwarded-for'] ||
            request.connection.remoteAddress ||
            request.socket.remoteAddress ||
            (request.connection.socket ? request.connection.socket.remoteAddress : null
            );
        var ips = [];
        for (var x = 0; x < ip.split(',').length; x++) {
            if (ip.split(',')[x].trim() == '127.0.0.1') {
                // do nothing
            } else {
                // add to array
                ips.push(ip.split(',')[x].trim());
            }
        }

        console.log('In /odata/publishofflineform: Attempt to save form from (' + ips + ')');
        var form = request.body;
        var timestamp = new Date();
        // Make sure we mark all the others as not active first.
        BwOfflineForm.update({
            bwFormActive: true
        }, {
            bwFormActive: false
        }, {
            multi: true
        }, function (error, mod) {
            if (!error) {
                // Now we can save this one, and it will be the only one marked as active.


                // Change from Update to SAVE!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
                var bwOfflineForm = new BwOfflineForm(
                    {
                        bwOfflineFormId: form.bwFormId,
                        //bwTenantId: form.bwTenantId,
                        //bwWorkflowAppId: form.bwWorkflowAppId,
                        bwBaseFormId: form.bwBaseFormId,
                        bwRequestType: form.bwRequestType,
                        Created: timestamp,
                        CreatedById: form.CreatedById,
                        CreatedByFriendlyName: form.CreatedByFriendlyName,
                        CreatedByEmail: form.CreatedByEmail,
                        //Modified: dtNow,
                        //ModifiedById: participantId,
                        //ModifiedByFriendlyName: participantFriendlyName,
                        //ModifiedByEmail: participantEmail,
                        //Description: description,
                        bwFormHtml: form.bwFormHtml, //JSON.stringify(thiz.options.CurrentWorkflow.Workflow)//, //, //, //JSON.stringify(thiz.options.CurrentWorkflow), // WE KNOW WE ARE NOT GETTING THE CORRECT JSON HERE!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
                        bwFormActive: true // The web service marks it true, so no need to send this. There canonly be 1 active one for a request type! And Publish makes it active, that is what it means. :)
                    });

                console.log(JSON.stringify(bwOfflineForm));

                bwOfflineForm.save(function (fsError) {
                    if (!fsError) {
                        console.log('SUCCESS');

                        var threatLevel = 'guarded'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.post.publishofflineform():';
                        var errorCode = null;
                        var message = 'The offline form has been updated. This is the form which is available to the user when they have not yet logged in.';
                        WriteToErrorLog(threatLevel, source, errorCode, message);

                        response.send('SUCCESS');
                    } else {
                        var msg = 'Error saving the form: ' + fsError;
                        // Exception section:
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.post.publishofflineform():1:';
                        var errorCode = null;
                        var message = msg;
                        WriteToErrorLog(threatLevel, source, errorCode, message);
                        //
                        //var results = { message: msg };
                        response.send(msg);

                    }
                });
            } else {
                var msg = 'Error updating bwForms: ' + error;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.post.publishofflineform()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var results = { message: msg };
                response.send(msg);
            }
        });
    } catch (e) {
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.publishofflineform()';
        var errorCode = null;
        var message = e.message;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        response.send('Exception in POST publishofflineform: ' + e.message + ', ' + e.stack);
    }
});


router.post('/odata/publishworkflow3', function (request, response) {
    try {

        var ip = request.headers['x-forwarded-for'] ||
            request.connection.remoteAddress ||
            request.socket.remoteAddress ||
            (request.connection.socket ? request.connection.socket.remoteAddress : null
            );
        var ips = [];
        for (var x = 0; x < ip.split(',').length; x++) {
            if (ip.split(',')[x].trim() == '127.0.0.1') {
                // do nothing
            } else {
                // add to array
                ips.push(ip.split(',')[x].trim());
            }
        }

        console.log('In /odata/publishworkflow3: Attempt to save workflow from (' + ips + ')');
        var workflow = request.body;
        var timestamp = new Date();
        // Make sure we mark all the others as not active first.
        BwWorkflow.update({
            bwWorkflowAppId: workflow.bwWorkflowAppId, bwRequestType: workflow.bwRequestType
        }, {
            bwWorkflowActive: false
        }, {
            multi: true
        }, function (error, mod) {
            if (!error) {
                // Now lets save/publish this new one.
                var bwWorkflowId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                    return v.toString(16);
                });
                var dtNow = new Date();
                var bwWorkflow = new BwWorkflow({
                    bwWorkflowId: bwWorkflowId,
                    bwTenantId: workflow.bwTenantId,
                    bwWorkflowAppId: workflow.bwWorkflowAppId,
                    Created: dtNow,
                    CreatedBy: workflow.CreatedBy,
                    CreatedById: workflow.CreatedById,
                    CreatedByEmail: workflow.CreatedByEmail,
                    bwRequestType: workflow.bwRequestType, // Added 3-18-2020 to support a workflow for each request type. 'ALL' or empty if there is just one workflow for all request types.
                    Description: workflow.Description,
                    bwWorkflowJson: workflow.bwWorkflowJson,
                    bwWorkflowActive: true
                });
                bwWorkflow.save(function (wsError) {
                    if (!wsError) {
                        response.send('SUCCESS');
                    } else {
                        var msg = 'Error updating the post /publishworkflow3: ' + wsError;
                        // Exception section:
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.post.publishworkflow3():1:';
                        var errorCode = null;
                        var message = msg;
                        WriteToErrorLog(threatLevel, source, errorCode, message);
                        //
                        //var results = { message: msg };
                        response.send(msg);
                    }
                });
            } else {
                var msg = 'Error updating the post /publishworkflow3: ' + error;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.post.publishworkflow3()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var results = { message: msg };
                response.send(msg);
            }
        });
    } catch (e) {
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.publishworkflow3()';
        var errorCode = null;
        var message = e.message;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        response.send('Error in POST publishworkflow3: ' + e.message);
    }
});

