                        var bwWorkflowAppId = orgRoles.bwWorkflowAppId;
                        var modifiedById = orgRoles.CreatedById;
                        var modifiedByFriendlyName = orgRoles.CreatedBy;
                        var modifiedByEmail = orgRoles.CreatedByEmail;

                        //
                        // First process the Global node.
                        //
                        console.log('promise synchronizeParticipantOrgRoles(). json.Global.Roles: ' + JSON.stringify(json.Global.Roles));
