router.post('/_bw/ForceUpdateOrgRolesConfiguration', function (request, response) {
    try {

        var ip = request.headers['x-forwarded-for'] ||
            request.connection.remoteAddress ||
            request.socket.remoteAddress ||
            (request.connection.socket ? request.connection.socket.remoteAddress : null
            );
        var ips = [];
        for (var x = 0; x < ip.split(',').length; x++) {
            if (ip.split(',')[x].trim() == '127.0.0.1') {
                // do nothing
            } else {
                // add to array
                ips.push(ip.split(',')[x].trim());
            }
        }

        console.log('In ForceUpdateOrgRolesConfiguration: Attempt to save bwOrgRoles from (' + ips + ')');
        //var json = {
        //    bwTenantId: tenantId,
        //    bwWorkflowAppId: workflowAppId,
        //    CreatedBy: participantFriendlyName,
        //    CreatedById: participantId,
        //    CreatedByEmail: participantEmail,
        //    bwOrgRolesJson: JSON.stringify(thiz.options.store.Global)//,
        //    //bwOrgRolesActive: true
        //};

        var bwTenantId = request.body.bwTenantId;
        var bwWorkflowAppId = request.body.bwWorkflowAppId;
        var createdById = request.body.CreatedById;
        var createdByFriendlyName = request.body.CreatedBy;
        var createdByEmail = request.body.CreatedByEmail;
        var bwOrgRolesJson = request.body.bwOrgRolesJson;
        var timestamp = new Date();

        // NEED TO REBASE THE DATA HERE...
        var json = {
            Global: JSON.parse(bwOrgRolesJson)
        }

        // save new record. First mark all as not active first.
        BwOrgRoles.update({
            bwWorkflowAppId: bwWorkflowAppId, bwOrgRolesActive: true
        }, {
            bwOrgRolesActive: false
        }, function (error, mod) {
            if (!error) {
                console.log('In ForceUpdateOrgRolesConfiguration/:bwWorkflowAppId/:RESET 333333<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<' + JSON.stringify(mod));
                // Now we can save this one, and it will be the only one marked as active.
                var bwOrgRolesId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                    return v.toString(16);
                });
                var bwOrgRoles = new BwOrgRoles(
                    {
                        bwOrgRolesId: bwOrgRolesId,
                        bwTenantId: bwTenantId,
                        bwWorkflowAppId: bwWorkflowAppId,
                        Created: timestamp,
                        CreatedBy: createdByFriendlyName,
                        CreatedById: createdById,
                        CreatedByEmail: createdByEmail,
                        bwOrgRolesJson: JSON.stringify(json),
                        bwOrgRolesActive: true
                    });
                bwOrgRoles.save(function (error) {
                    if (!error) {
                        bwOrgRoles.save();
                        console.log('SAVED FROM POST ForceUpdateOrgRolesConfiguration. RETURNING "SUCCESS".');
                        response.send('SUCCESS');
                    } else {
                        response.send('Error in POST ForceUpdateOrgRolesConfiguration(): ' + error);
                    }
                });
            } else {
                var msg = 'Error updating the post /ForceUpdateOrgRolesConfiguration:55556666 ' + error;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.get.ForceUpdateOrgRolesConfiguration()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var results = { message: msg };
                response.send(msg);
            }
        });

    } catch (e) {
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.OrgRolesConfiguration()';
        var errorCode = null;
        var message = e.message;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        response.send('Error in POST ForceUpdateOrgRolesConfiguration: ' + e.message + ', ' + e.stack);
    }
});




















