function formatCurrency(num) {
    //num = num.toString().replace(/\$|\,/g, '');
    //if (isNaN(num))
    //    num = "0";
    //var sign = (num == (num = Math.abs(num)));
    //num = Math.floor(num * 100 + 0.50000000001);
    //var cents = num % 100;
    //num = Math.floor(num / 100).toString();
    //if (cents < 10)
    //    cents = "0" + cents;
    //for (var i = 0; i < Math.floor((num.length - (1 + i)) / 3) ; i++)
    //    num = num.substring(0, num.length - (4 * i + 3)) + ',' +
    //    num.substring(num.length - (4 * i + 3));
    //return (((sign) ? '' : '-') + '$' + num + '.' + cents);



    // selectedCurrencySymbol. Values include: Dollar, Pound, Euro, Rand, Franc, Yen, Rouble, Peso, Rupee, Guilder.
    // Now we have to disable the button for the page we are on at the moment.
    var currencySymbol = '';
    switch (selectedCurrencySymbol) {
        case 'Dollar':
            currencySymbol = '$';
            break;
        case 'Pound':
            currencySymbol = '£';
            break;
        case 'Euro':
            currencySymbol = '€';
            break;
        case 'Rand':
            currencySymbol = 'R';
            break;
        case 'Franc':
            currencySymbol = '?';
            break;
        case 'Yen':
            currencySymbol = '¥';
            break;
        case 'Rouble':
            currencySymbol = '?';
            break;
        case 'Peso':
            currencySymbol = '?';
            break;
        case 'Rupee':
            currencySymbol = '?';
            break;
        case 'Guilder':
            currencySymbol = 'ƒ';
            break;
        default:
            currencySymbol = '$';
            break;
    }

    if (num) {
        //num = num.toString().replace(/\$|\,/g, '');
        num = num.toString().replace(/\$|\,/g, '');

        num = num.toString().replace(/\£|\,/g, '');
        num = num.toString().replace(/\€|\,/g, '');
        num = num.toString().replace(/\R|\,/g, '');
        num = num.toString().replace(/\?|\,/g, '');
        num = num.toString().replace(/\¥|\,/g, '');
        num = num.toString().replace(/\?|\,/g, '');
        num = num.toString().replace(/\?|\,/g, '');
        num = num.toString().replace(/\?|\,/g, '');
        num = num.toString().replace(/\ƒ|\,/g, '');

        if (isNaN(num))
            num = "0";
        var sign = (num == (num = Math.abs(num)));
        num = Math.floor(num * 100 + 0.50000000001);
        var cents = num % 100;
        num = Math.floor(num / 100).toString();
        if (cents < 10)
            cents = "0" + cents;
        for (var i = 0; i < Math.floor((num.length - (1 + i)) / 3); i++)
            num = num.substring(0, num.length - (4 * i + 3)) + ',' +
                num.substring(num.length - (4 * i + 3));
        return (((sign) ? '' : '-') + currencySymbol + num + '.' + cents);
    } else {
        return currencySymbol + '0.00'; //0; // This was 0 but I changed it 4-15-18 3-36am ast.
    }
}

