router.post('/_bw/startimaplistener', function (request, response) {
    // This is called from the admin page when the administrator wants to restart the imap listener. It stops for some reason!!! :( This is a temporary fix until we get the final solution.
    mailListener = new MailListener({
        username: "todd_hiltz@hotmail.com",
        password: "Novascotia11",
        host: "imap-mail.outlook.com",
        port: 993, // imap port 
        tls: true, // use secure connection 
        tlsOptions: {
            rejectUnauthorized: false
        },
        mailbox: "INBOX", // mailbox to monitor 
        markSeen: true, // all fetched email will be marked as seen and not fetched next time 
        fetchUnreadOnStart: true // use it only if you want to get all unread email on lib start. Default is `false` 
    });

    mailListener.start();

    mailListener.on("server:connected", function () {
        imapConnected = true;
        console.log("imapConnected");
        // Exception section:
        var threatLevel = 'low'; // severe, high, elevated, guarded, low.
        var source = 'start.js.mailListener.on(server:connected)';
        var errorCode = null;
        var message = 'imapConnected';
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
    });

    mailListener.on("server:disconnected", function () {
        imapConnected = false;
        console.log("imapDisconnected");
        // Exception section:
        var threatLevel = 'elevated'; // severe, high, elevated, guarded, low.
        var source = 'start.js.mailListener.on(server:disconnected)';
        var errorCode = null;
        var message = 'imapDisconnected';
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        mailListener.start(); // Todd: Not sure if this is the best way but we will see!
    });

    mailListener.on("error", function (error) {
        imapConnected = false;
        console.log(error);
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.mailListener.on(error)';
        var errorCode = null;
        var message = error;
        WriteToErrorLog(threatLevel, source, errorCode, message);
    });

    mailListener.on("mail", function (mail, seqno, attributes) {
        // do something with mail object including attachments 
        console.log('A new email has arrived.');
        // The following is all of the data from gmail. Please leave if not needed just comment out.
        var html = mail.html;
        var subject = mail.subject;
        var references = mail.references;
        var messageId = mail.messageId;
        var inReplyTo = mail.inReplyTo;
        var from = mail.from;
        //var fromAddress = mail.from.address; // 'no-reply@squarespace.com'.
        //var fromName = mail.from.name; // 'Squarespace'.
        var to = mail.to;
        var date = mail.date;
        var receivedDate = mail.receivedDate; // This date is later than the date above. In my test by 5 seconds.
        if (subject.indexOf('Budget Workflow: A New Order has Arrived') > -1) {
            // We have a new order!
            console.log('This email is a New Order! Processing...');
            // Get the Invoice Number.
            var char1 = html.indexOf('Order #');
            var char2 = html.indexOf('BILLED TO:');
            var strTemp = html.substring(char1, char2);
            //msg += 'strTemp: ' + strTemp + '\r\n';
            var char1 = strTemp.indexOf('Order #');
            //var char1 = orderNumberText.indexOf('Order #');
            var invoiceNumber = strTemp.substring(char1 + 6, char1 + 12); // Invoice Number.
            // Get the rest of the values.
            var char1 = html.indexOf('BILLED TO:');
            var restOfDocument = html.substring(char1, html.length);
            // First get the "Billed To:" details. 
            var char1 = restOfDocument.indexOf('<div');
            var char2 = restOfDocument.indexOf('</div>');
            var billedToDetails = restOfDocument.substring(char1, char2 + 6); // The whole div tag section with the billed to details.
            var char1 = billedToDetails.indexOf('<span');
            var strTemp = billedToDetails.substring(char1, billedToDetails.length);
            var char1 = strTemp.indexOf('">');
            var char2 = strTemp.indexOf('</span');
            var billedToEmail = strTemp.substring(char1 + 2, char2).trim(); // Email.
            // Now get the Order Summary.
            var char1 = restOfDocument.indexOf('Order Summary');
            var strTemp = restOfDocument.substring(char1, restOfDocument.length);
            var char1 = strTemp.indexOf('<table');
            var char2 = strTemp.indexOf('class="page-break-section"'); // This is before the footer in the email.
            var orderSummarySection = strTemp.substring(char1, char2);
            // Now that we have everything, we need to break down the order into it's details.
            var char1 = orderSummarySection.indexOf('</tr>');
            var strTemp = orderSummarySection.substring(char1 + 4, orderSummarySection.length);
            var char1 = strTemp.indexOf('</tr>');
            var unprocessedPartOfInvoice = strTemp.substring(char1 + 5, strTemp.length);
            // Start getting invoice items.
            var invoiceItems = [];
            var lastChar = 0;
            for (var i = 0; i < 100; i++) { // doesn't need wrap.
                var char2 = unprocessedPartOfInvoice.indexOf('</tr>'); // Each invoice item is a <tr></tr>.
                var skuCheck = unprocessedPartOfInvoice.indexOf('SQ');
                if (skuCheck == -1) {
                    break;
                }
                var invoiceItem = unprocessedPartOfInvoice.substring(0, char2 + 5);
                unprocessedPartOfInvoice = unprocessedPartOfInvoice.substring(char2 + 4, unprocessedPartOfInvoice.length);
                // Get the details of this invoice item.
                var char1 = invoiceItem.indexOf('<td');
                var char2 = invoiceItem.indexOf('</td>');
                var titleAndSkuSection = invoiceItem.substring(char1, char2 + 5);
                //msg += 'titleAndSkuSection: ' + titleAndSkuSection + '\r\n';
                var lastChar = char2 + 4;
                var char1 = invoiceItem.indexOf('<td', lastChar);
                var char2 = invoiceItem.indexOf('</td>', lastChar);
                var quantitySection = invoiceItem.substring(char1, char2 + 5);
                //msg += 'quantitySection: ' + quantitySection + '\r\n';
                // Now that we have the sections, lets get the values.
                var charTmp = titleAndSkuSection.indexOf('<span');
                var char1 = titleAndSkuSection.indexOf('>', charTmp);
                var char2 = titleAndSkuSection.indexOf('</span>');
                var itemTitle = titleAndSkuSection.substring(char1 + 1, char2);
                var charTmp = titleAndSkuSection.indexOf('<span', char2);
                var char1 = titleAndSkuSection.indexOf('>', charTmp);
                var char2 = titleAndSkuSection.indexOf('</span>', charTmp);
                var itemSku = titleAndSkuSection.substring(char1 + 1, char2);
                var char1 = itemSku.indexOf('SQ');
                itemSku = itemSku.substring(char1, char1 + 9);
                // Get the quantity.
                var charTmp = quantitySection.indexOf('<div>');
                var char1 = quantitySection.indexOf('>', charTmp);
                var char2 = quantitySection.indexOf('</div>');
                var itemQuantity = quantitySection.substring(char1 + 1, char2);
                var char1 = itemQuantity.indexOf('>');
                itemQuantity = itemQuantity.substring(char1 + 1, itemQuantity.length).trim();
                // Create the object and add to the array.
                var licenseId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                    return v.toString(16);
                });
                var invoiceItem2 = [];
                invoiceItem2 = new Array(4);
                invoiceItem2[0] = itemSku;
                invoiceItem2[1] = itemTitle;
                invoiceItem2[2] = itemQuantity;
                invoiceItem2[3] = licenseId;
                invoiceItems.push(invoiceItem2);
            }

            var msg = '';
            //msg += 'subject: ' + subject + '\r\n';
            //msg += 'from: ' + JSON.stringify(from) + '\r\n';
            //msg += 'date: ' + date + '\r\n';
            //msg += 'receivedDate: ' + receivedDate + '\r\n';
            //msg += 'invoiceNumber: ' + invoiceNumber + '\r\n';
            //msg += 'billedToDetails: ' + billedToDetails + '\r\n';
            //msg += 'billedToEmail: ' + billedToEmail + '\r\n\r\n';
            for (var i = 0; i < invoiceItems.length; i++) { // doesn't need wrap.
                // msg += 'Invoice item ' + (i + 1).toString() + '<br />';
                msg += 'SKU: ' + invoiceItems[i][0] + '<br />';
                msg += 'Title: ' + invoiceItems[i][1] + '<br />';
                msg += 'Quantity: ' + invoiceItems[i][2] + '<br />';
                msg += 'License: ' + invoiceItems[i][3] + '<br /><br />';
            }
            //msg += '';
            //msg += '';

            // Now that it has been parsed, we need to save the details to the database in the BwWorkflowAppLicense object.
            for (var i = 0; i < invoiceItems.length; i++) { // doesn't need wrap.
                var sku = invoiceItems[i][0];
                var title = invoiceItems[i][1];
                var quantity = invoiceItems[i][2];
                var license = invoiceItems[i][3];

                var packageCategory;
                if (sku == 'SQ9955673') packageCategory = 'bronze';
                else if (sku == 'SQ4071376') packageCategory = 'silver';
                else if (sku == 'SQ6700506') packageCategory = 'gold';


                var bwWorkflowAppLicense = new BwWorkflowAppLicense(
                    {
                        bwWorkflowAppLicenseId: license,
                        InvoiceNumber: invoiceNumber,
                        LicenseNotificationSentToEmail: billedToEmail,
                        LicenseSku: sku,
                        LicenseTitle: title,
                        LicenseQuantity: quantity,
                        LicenseClaimed: 'false',
                        LicenseNotificationSent: 'false', // This is important because it triggers if the task timer picks it up.
                        //LicenseType: String, // yearlysubscription, additionalbudgetrequests.
                        LicensePackageCategory: packageCategory // bronze, silver, gold.
                        //LicenseQuantityType: String, // workflowapps, neworsupplementalrequests.
                        //LicenseEmailFromStripeOrSquarespace: JSON.stringify(mail) // We put the content of the notification email here. 
                    }
                );
                bwWorkflowAppLicense.save(function (error) {
                    if (!error) {
                        bwWorkflowAppLicense.save();
                        console.log('SAVED A NEW LICENSE.');
                        //if (i == (invoiceItems.length - 1)) { // Only send the email once they have all been added to the database.
                        //    // Email the licenses!
                        //    writeTimerLogEntry('Preparing to email the licenses to ' + billedToEmail);
                        //    var unsubscribeUrl = globalUrlPrefix + globalUrl + '/my.html?participant=' + billedToEmail + '&unsubscribe=true';
                        //    var unsubscribeMessage = '<br /><br /><a href="' + unsubscribeUrl + '">If you wish to stop receiving these emails please click here to unsubscribe.</a>';
                        //    var emailSubject = "Your new licenses for your budget workflow.";
                        //    var emailBody = "Your new licenses for your budget workflow are included below.<br />Click here to go to your budget workflow, then go to \"Configuration\" > \"Settings\", and add them to the licenses list.<br /><br />" + msg + "<br /><br />" + unsubscribeMessage;
                        //    sendgrid.send({
                        //        to: billedToEmail, 
                        //        from: 'Budget Workflow ?? <info@budgetworkflow.com>',
                        //        subject: emailSubject,
                        //        //text: emailBody
                        //        html: emailBody
                        //    }, function (sgError, sgResponse) {
                        //        if (sgError) {
                        //            writeTimerLogEntry('Error in mailListener.on.mail():3:Sendgrid email response: '_; // + sgError);
                        //        //response.send('Error in mailListener.on.mail():3:Sendgrid email response: ' + sgError);
                        //        } else {
                        //            writeTimerLogEntry('Sendgrid email response: '); // + sgResponse.message);
                        //        }
                        //    });
                        //}
                    } else {
                        writeTimerLogEntry('Error in mailListener.on.mail.bwWorkflowAppLicense.save(): '); // + error);
                    }
                });
            }

            //fs.writeFile("c:/tmp/test.txt", msg, function (err) {
            //    if (err) {
            //        return console.log(err);
            //    }

            //    console.log("The file was saved!");
            //}); 
        }

    });

    mailListener.on("attachment", function (attachment) {
        console.log(attachment.path);
    });

    response.send('SUCCESS');
});

