function getListOfBackfillRoles(bwWorkflowAppId) {
    return new Promise(function (resolve, reject) {
        try {
            console.log('In getListOfBackfillRoles. bwWorkflowAppId: ' + bwWorkflowAppId);
            BwRole.find({
                bwWorkflowAppId: bwWorkflowAppId
            }, function (rfError, rfResult) {
                if (!rfError) {
                    BwOrgRoles.find({
                        bwWorkflowAppId: bwWorkflowAppId, bwOrgRolesActive: true
                    }, function (orfError, orfResult) {
                        if (!orfError) {
                            // Go through the JSON and make sure the RoleId or RoleName does not already exist.
                            if (orfResult.length != 1) {
                                // There is a problem, because there should only ever be 1 active BwOrgROles record here!!! bwOrgRolesJson is the definition for the organization.
                                var msg = 'Error in POST /_bw/getListOfBackfillRoles:4-4: BwOrgRoles.length != 1!!! Too many bwOrgRolesJson to choose from.';
                                // Exception section:
                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.POST.getListOfBackfillRoles()';
                                var errorCode = null;
                                var message = msg;
                                WriteToErrorLog(threatLevel, source, errorCode, message);
                                //
                                var results = {
                                    message: msg
                                };
                                //response.send(results);
                                resolve(results);
                            } else {
                                var json = JSON.parse(orfResult[0].bwOrgRolesJson);
                                var roles = [];
                                if (json.Global.Roles) {
                                    for (var i = 0; i < json.Global.Roles.length; i++) {
                                        var isRoleAlreadyInArray = false;
                                        for (var r = 0; r < roles.length; r++) {
                                            if (roles[r].RoleId == json.Global.Roles[i].RoleId) {
                                                isRoleAlreadyInArray = true;
                                                break;
                                            }
                                        }
                                        if (isRoleAlreadyInArray == false) {
                                            var role = {
                                                RoleId: json.Global.Roles[i].RoleId, RoleName: json.Global.Roles[i].RoleName
                                            };
                                            roles.push(role);
                                        }
                                    }
                                }
                                for (var d = 0; d < json.Global.Divisions.Items.length; d++) {
                                    if (json.Global.Divisions.Items[d].Roles) {
                                        for (var i = 0; i < json.Global.Divisions.Items[d].Roles.length; i++) {
                                            var isRoleAlreadyInArray = false;
                                            for (var r = 0; r < roles.length; r++) {
                                                if (roles[r].RoleId == json.Global.Divisions.Items[d].Roles[i].RoleId) {
                                                    isRoleAlreadyInArray = true;
                                                    break;
                                                }
                                            }
                                            if (isRoleAlreadyInArray == false) {
                                                var role = {
                                                    RoleId: json.Global.Divisions.Items[d].Roles[i].RoleId, RoleName: json.Global.Divisions.Items[d].Roles[i].RoleName
                                                };
                                                roles.push(role);
                                            }
                                        }
                                    }
                                    for (var g = 0; g < json.Global.Divisions.Items[d].Groups.Items.length; g++) {
                                        if (json.Global.Divisions.Items[d].Groups.Items[g].Roles) {
                                            for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].Roles.length; i++) {
                                                var isRoleAlreadyInArray = false;
                                                for (var r = 0; r < roles.length; r++) {
                                                    if (roles[r].RoleId == json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].RoleId) {
                                                        isRoleAlreadyInArray = true;
                                                        break;
                                                    }
                                                }
                                                if (isRoleAlreadyInArray == false) {
                                                    var role = {
                                                        RoleId: json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].RoleId, RoleName: json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].RoleName
                                                    };
                                                    roles.push(role);
                                                }
                                            }
                                        }
                                        for (var e = 0; e < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items.length; e++) {
                                            if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles) {
                                                for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles.length; i++) {
                                                    var isRoleAlreadyInArray = false;
                                                    for (var r = 0; r < roles.length; r++) {
                                                        if (roles[r].RoleId == json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].RoleId) {
                                                            isRoleAlreadyInArray = true;
                                                            break;
                                                        }
                                                    }
                                                    if (isRoleAlreadyInArray == false) {
                                                        var role = {
                                                            RoleId: json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].RoleId, RoleName: json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].RoleName
                                                        };
                                                        roles.push(role);
                                                    }
                                                }
                                            }
                                            for (var l = 0; l < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items.length; l++) {
                                                if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles) {
                                                    for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles.length; i++) {
                                                        var isRoleAlreadyInArray = false;
                                                        for (var r = 0; r < roles.length; r++) {
                                                            if (roles[r].RoleId == json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].RoleId) {
                                                                isRoleAlreadyInArray = true;
                                                                break;
                                                            }
                                                        }
                                                        if (isRoleAlreadyInArray == false) {
                                                            var role = {
                                                                RoleId: json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].RoleId, RoleName: json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].RoleName
                                                            };
                                                            roles.push(role);
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                // So far the RoleId or RoleName does not exist already. Now we have to check the Workflow json definitions...
                                BwWorkflow.find({
                                    bwWorkflowAppId: bwWorkflowAppId, bwWorkflowActive: true
                                }, function (wfError, wfResult) {
                                    if (!wfError) {
                                        // Go through the Workflow JSON and check that the RoleId or RoleName does not already exist.
                                        if (!(wfResult.length > 0)) {
                                            var msg = 'No active workflow definitions could be found. This action cannot proceed.';
                                            var results = {
                                                message: msg, Roles: roles
                                            };
                                            //response.send(results);
                                            resolve(results);
                                        } else {
                                            for (var w = 0; w < wfResult.length; w++) {
                                                var json = {
                                                    Workflow: JSON.parse(wfResult[w].bwWorkflowJson)
                                                }

                                                if (!json.Workflow) {
                                                    console.log('');
                                                    console.log('');
                                                    console.log('ERROR json.Workflow is undefined. Expected value from wfResult[w].bwWorkflowJson. wfResult[w]: ' + JSON.stringify(wfResult[w]));
                                                    console.log('');
                                                    console.log('');
                                                } else {
                                                    // Iterate through the steps. Then the informs, then the assigns. Make an array of the roles. { RoleId, RoleName }
                                                    for (var i = 0; i < json.Workflow.Steps.Step.length; i++) {
                                                        var stepName = json.Workflow.Steps.Step[i]["@Name"];
                                                        if (stepName == 'Create' || stepName == 'Revise' || stepName == 'Admin') {
                                                            // Do nothing, not checking these steps.
                                                        } else {
                                                            // Check Inform roles.
                                                            if (json.Workflow.Steps.Step[i].OnStart && json.Workflow.Steps.Step[i].OnStart.Inform) {
                                                                if (json.Workflow.Steps.Step[i].OnStart.Inform.length > 0) {
                                                                    for (var j = 0; j < json.Workflow.Steps.Step[i].OnStart.Inform.length; j++) {
                                                                        var isRoleAlreadyInArray = false;
                                                                        for (var r = 0; r < roles.length; r++) {
                                                                            if (roles[r].RoleId == json.Workflow.Steps.Step[i].OnStart.Inform[j]["@Role"]) {
                                                                                isRoleAlreadyInArray = true;
                                                                                break;
                                                                            }
                                                                        }
                                                                        if (isRoleAlreadyInArray == false) {
                                                                            var role = {
                                                                                RoleId: json.Workflow.Steps.Step[i].OnStart.Inform[j]["@Role"], RoleName: json.Workflow.Steps.Step[i].OnStart.Inform[j]["@RoleName"]
                                                                            };
                                                                            roles.push(role);
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                            // Check Assign roles.
                                                            if (json.Workflow.Steps.Step[i].Assign) {
                                                                if (json.Workflow.Steps.Step[i].Assign.length > 0) {
                                                                    for (var j = 0; j < json.Workflow.Steps.Step[i].Assign.length; j++) {
                                                                        var isRoleAlreadyInArray = false;
                                                                        for (var r = 0; r < roles.length; r++) {
                                                                            if (roles[r].RoleId == json.Workflow.Steps.Step[i].Assign[j]["@Role"]) {
                                                                                isRoleAlreadyInArray = true;
                                                                                break;
                                                                            }
                                                                        }
                                                                        if (isRoleAlreadyInArray == false) {
                                                                            var role = {
                                                                                RoleId: json.Workflow.Steps.Step[i].Assign[j]["@Role"], RoleName: json.Workflow.Steps.Step[i].Assign[j]["@RoleName"]
                                                                            };
                                                                            roles.push(role);
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                            // Before we send to the client, we ned to remove any ones that already exist in the BwRole table.
                                            for (var i = 0; i < rfResult.length; i++) {
                                                for (var r = 0; r < roles.length; r++) {
                                                    if (roles[r].RoleId == rfResult[i].RoleId) {
                                                        // Remove this one from the roles array.
                                                        roles.splice(r, 1);
                                                        break;
                                                    }
                                                }
                                            }
                                            // Now check if the ADMIN role is in the BwRole table. If not, return it because this role is required!!!!!!!!!!!!!!!!
                                            var adminRoleExists = false;
                                            for (var i = 0; i < rfResult.length; i++) {
                                                if (rfResult[i].RoleId == 'ADMIN') {
                                                    adminRoleExists = true;
                                                    break;
                                                }
                                            }
                                            if (adminRoleExists == false) {
                                                var adminRole = {
                                                    RoleId: 'ADMIN',
                                                    RoleName: 'Workflow Administrator'//,
                                                    //RoleDescription: 'Only 1 person can be assigned this role.<br /><ul><li>This role has to approve all new requests before they continue through the approval process.</li><li>This role receives tasks when no one has been specified for a role in the organization.</li><li>This is the only role that can perform actions on behalf of other roles.</li></ul>'
                                                }
                                                roles.push(adminRole);
                                            }
                                            var results = {
                                                message: 'SUCCESS',
                                                Roles: roles
                                            };
                                            //response.send(results);
                                            resolve(results);
                                        }
                                    }
                                });
                            }
                        }
                    });
                } else {
                    var msg = 'Error in POST /_bw/getListOfBackfillRoles:1: ' + rfError;
                    // Exception section:
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.POST.getListOfBackfillRoles()';
                    var errorCode = null;
                    var message = msg;
                    WriteToErrorLog(threatLevel, source, errorCode, message);
                    //
                    var results = {
                        message: msg
                    };
                    //response.send(results);
                    resolve(results);
                }
            });
        } catch (e) {
            var msg = 'Exception in POST /_bw/getListOfBackfillRoles:2:' + e.message;
            // Exception section:
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js.POST.getListOfBackfillRoles()';
            var errorCode = null;
            var message = msg;
            WriteToErrorLog(threatLevel, source, errorCode, message);
            //
            var results = {
                message: msg
            };
            resolve(results);
        }
    });
};

