        var bwDocumentXml = request.body.bwDocumentXml;
        modifiedById = request.body.ModifiedById;
        modifiedByFriendlyName = request.body.ModifiedByFriendlyName;
        modifiedByEmail = request.body.ModifiedByEmail;
