function addToAIConversation_UserActionsLog(bwAIConversation_UserActionsLog1) {
    return new Promise(function (resolve, reject) {
        try {
            console.log('In addToAIConversation_UserActionsLog().'); // BwAIConversation_UserActionsLog

            var guid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                return v.toString(16);
            });

            var bwAIConversation_UserActionsLog = new BwAIConversation_UserActionsLog({
                bwAIConversation_UserActionsLogId: guid,
                bwWorkflowAppId: bwAIConversation_UserActionsLog1.bwWorkflowAppId,

                // bwBudgetRequest
                bwBudgetRequestId: bwAIConversation_UserActionsLog1.bwBudgetRequestId,
                Title: bwAIConversation_UserActionsLog1.Title,
                ProjectTitle: bwAIConversation_UserActionsLog1.ProjectTitle,

                Timestamp: new Date(),

                // This user took the action
                ParticipantId: bwAIConversation_UserActionsLog1.ParticipantId,
                ParticipantEmail: bwAIConversation_UserActionsLog1.ParticipantEmail,
                ParticipantFriendlyName: bwAIConversation_UserActionsLog1.ParticipantFriendlyName,

                // This is the action. 
                // For example, "Attachment". Then the "Action" would be "Added"... User Todd Hiltz[participant] added[action] an attachment[object] to request [bwBudgetRequest].
                // Example #2: User Todd Hiltz Saved/Published the request.
                Action: bwAIConversation_UserActionsLog1.Action, // ['added', 'xx', 'xx']
                Action_ObjectContext: bwAIConversation_UserActionsLog1.Action_ObjectContext, // ['attachment', 'xx', 'xx']
                Action_Message: bwAIConversation_UserActionsLog1.Action_Message
            });

            bwAIConversation_UserActionsLog.save(function (aicError) {
                try {
                    if (aicError) {

                        var msg = 'Error in addToAIConversation_UserActionsLog(). aicError: ' + aicError;
                        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.addToAIConversation_UserActionsLog()';
                        var errorCode = null;
                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                        var result = {
                            status: 'ERROR',
                            message: msg
                        }
                        reject(result);

                    } else {

                        var result = {
                            status: 'SUCCESS',
                            message: msg
                        }
                        resolve(result);

                    }

                } catch (e) {

                    var msg = 'Exception in addToAIConversation_UserActionsLog():2: ' + e.message + ', ' + e.stack;
                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.addToAIConversation_UserActionsLog()';
                    var errorCode = null;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                    var result = {
                        status: 'EXCEPTION',
                        message: msg
                    }
                    reject(result);

                }
            });

        } catch (e) {

            var msg = 'Exception in addToAIConversation_UserActionsLog():1: ' + e.message + ', ' + e.stack;
            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
            var source = 'start.js.addToAIConversation_UserActionsLog()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg);

            var result = {
                status: 'EXCEPTION',
                message: msg
            }
            reject(result);

        }
    });
}

