router.post('/_bw/bwbudgetrequests/assignponumber', function (request, response) {
    try {
        console.log('assignponumber METHOD INVOKED');
        var bwBudgetRequestId = request.body.bwBudgetRequestId;
        var modifiedById = request.body.ModifiedById;
        var modifiedByFriendlyName = request.body.ModifiedByFriendlyName;
        var modifiedByEmail = request.body.ModifiedByEmail;
        var bwDocumentXml = request.body.bwDocumentXml;
        var modified = new Date(); // Converted from getCreatedTimestamp(); 2-6-2022
        //var participantFriendlyName = request.body.participantFriendlyName;

        var AppWebUrl = globalUrlPrefix + globalUrl; //'http://preview.budgetworkflow.com';
        var _appWebUrl = globalUrlPrefix + globalUrl; //'http://preview.budgetworkflow.com';
        var _budgetWorkflowStatus;
        var budgetAmount;
        var functionalAreaId;
        // If the token is greater than zero, find the current value and add one to it and continue!
        console.log('STARTING TO UPDATE BUDGET REQUEST. bwBudgetRequestId:' + bwBudgetRequestId);
        var timestamp1 = new Date();
        BwBudgetRequest.update({
            bwBudgetRequestId: bwBudgetRequestId
        }, {
            ARStatus: 'Active', ARStatusModifiedTimestamp: timestamp1, BudgetWorkflowStatus: 'PO# Issued', BudgetWorkflowStatusModifiedTimestamp: timestamp1, CurrentOwner: '', CurrentOwnerId: '', CurrentOwnerEmail: '', ModifiedById: modifiedById, ModifiedByFriendlyName: modifiedByFriendlyName, ModifiedByEmail: modifiedByEmail, Modified: modified, bwDocumentXml: bwDocumentXml
        }, function (err, mod) {
            if (err) {
                var msg = 'ERROR UPDATING THE BUDGET REQUESTxcx7. bwBudgetRequestId:' + bwBudgetRequestId;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.POST.bwbudgetrequests/assignponumber()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var results = { message: msg };
                console.log(msg);
            } else {
                console.log('UPDATE COMPLETED');

                // First we have to mark the "Assign Budget" task as complete.
                var outcome = "PO# Issued";
                var modified = new Date(); // Converted from getCreatedTimestamp(); 2-6-2022
                var taskData1 = {
                    //'CW_BA_CustomOutcome' : outcome,
                    'bwStatus': 'Completed',
                    'bwTaskOutcome': outcome + " by " + modifiedByFriendlyName,
                    'bwPercentComplete': 100,
                    'Modified': modified,
                    'bwHasBeenProcessedByTheWorkflowEngine': true //'true'
                };
                console.log("STARTING TO UPDATE BwWorkflowTask");
                BwWorkflowTask.update({
                    bwRelatedItemId: bwBudgetRequestId, bwPercentComplete: 0, TrashBin: false
                }, taskData1, function (err, mod) {
                    if (err) {
                        var msg = err;
                        // Exception section:
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.POST.bwbudgetrequests/assignponumber()';
                        var errorCode = null;
                        var message = msg;
                        WriteToErrorLog(threatLevel, source, errorCode, message);
                        //
                        //var results = { message: msg };
                        console.log(msg);
                    }
                    else {
                        console.log('UPDATE COMPLETED');
                        response.send('The PO# has been issued for the AR, and it has been marked as \'Active\'.');
                    }
                });
            }
        });

    } catch (e) {
        var msg = 'Error in POST /bwbudgetrequests/assignponumber:' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.bwbudgetrequests/assignponumber()';
        var errorCode = null;
        var message = msg;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        //var results = { message: msg };
        response.send(msg);
    }
});





router.get('/_bw/gettenantdetails/:bwTenantId', function (request, response) {
    try {
        var bwTenantId = request.params.bwTenantId;
        BwTenant.find({
            bwTenantId: bwTenantId
        }, function (error, result) {
            if (error) {
                var msg = 'Error in GET /gettenantdetails/:1: ' + error;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.GET.gettenantdetails/:()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var result = { message: msg };

                var data = {
                    d: {
                        results: null, message: 'FAILED'
                    }
                };
                response.send(data);

                //response.send(msg);
            } else {
                var data = {
                    d: {
                        results: result, message: 'SUCCESS'
                    }
                };
                response.send(data);
            }
        });
    } catch (e) {
        var msg = 'Error in GET /gettenantdetails/:2: ' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.GET.gettenantdetails/()';
        var errorCode = null;
        var message = msg;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        //var result = { message: msg };
        var data = {
            d: {
                results: null, message: 'FAILED'
            }
        };
        response.send(data);

        //response.send(msg);
    }
});


