// THIS IS THE ONLY PLACE WHERE WE SHOULD BE REMOVING A SUPPLEMENTAL FROM A REQUEST. 4-7-2024.
/////////////////////////////////////////////////////////////////////////////////////////////////////////////
router.post('/_bw/removesupplementalfromarequest', function (request, response) {
    try {
        console.log('In start.js.removesupplementalfromarequest().');

        var bwParticipantId_LoggedIn = request.body.bwParticipantId_LoggedIn;
        var bwActiveStateIdentifier = request.body.bwActiveStateIdentifier;
        var bwWorkflowAppId_LoggedIn = request.body.bwWorkflowAppId_LoggedIn;

        var promise = AuthorizeWebServiceCall(request, bwParticipantId_LoggedIn, bwActiveStateIdentifier, bwWorkflowAppId_LoggedIn, 'participant');
        promise.then(function (results) {
            try {

                if (results.status == 'AUTHORIZED') {

                    // AUTHORIZED.
                    console.log('AUTHORIZED in /removesupplementalfromarequest().');
                    console.log('AUTHORIZED');
                    console.log('AUTHORIZED');

                    var bwParticipantEmail = request.body.bwParticipantEmail;
                    var bwParticipantFriendlyName = request.body.bwParticipantFriendlyName;

                    var supplemental_bwBudgetRequestId = request.body.supplemental_bwBudgetRequestId;
                    var master_bwBudgetRequestId = request.body.master_bwBudgetRequestId;

                    if (!(supplemental_bwBudgetRequestId && master_bwBudgetRequestId) || (supplemental_bwBudgetRequestId === 'undefined') || (master_bwBudgetRequestId === 'undefined')) { // I like how this is done, consider this elsewhere, more thought required. 3-2-2024.

                        var msg = 'Error in start.js.removesupplementalfromarequest(). Invalid value(s): supplemental_bwBudgetRequestId: ' + supplemental_bwBudgetRequestId + ', master_bwBudgetRequestId: ' + master_bwBudgetRequestId;
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.removesupplementalfromarequest()';
                        var errorCode = null;
                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                        var result = {
                            status: 'ERROR',
                            message: msg
                        }
                        response.send(result);

                    } else {

                        //
                        //
                        // 4-7-2024. 
                        //
                        //
                        // IsSupplementalRequest: Boolean, // true or false. 4-6-2024 changed to Boolean.
                        // RelatedBudgetRequestId: String, // If it is a supplemental request, then the original request Id needs to be here.
                        //
                        // WE ARE ALSO PUTTING THESE VALUES IN THE bwRequestJson so that they can be rendered in the Executive Summaries.
                        //

                        BwBudgetRequest.findOne({ bwWorkflowAppId: bwWorkflowAppId_LoggedIn, bwBudgetRequestId: supplemental_bwBudgetRequestId }, function (brfError, brfResult) {
                            try {
                                if (brfError) {

                                    var msg = 'Error in start.js.removesupplementalfromarequest(). brfError: ' + brfError;
                                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.removesupplementalfromarequest()';
                                    var errorCode = null;
                                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                                    var result = {
                                        status: 'ERROR',
                                        message: msg
                                    }
                                    response.send(result);

                                } else {

                                    // WE ARE ALSO PUTTING THESE VALUES IN THE bwRequestJson so that they can be rendered in the Executive Summaries.
                                    var bwRequestJson = JSON.parse(brfResult.bwRequestJson);
                                    bwRequestJson["IsSupplementalRequest"] = false;
                                    bwRequestJson["RelatedBudgetRequestId"] = null;

                                    var bwRequestJson2 = JSON.stringify(bwRequestJson);

                                    BwBudgetRequest.updateOne({ bwWorkflowAppId: bwWorkflowAppId_LoggedIn, bwBudgetRequestId: supplemental_bwBudgetRequestId }, { $set: { IsSupplementalRequest: false, RelatedBudgetRequestId: null, bwRequestJson: bwRequestJson2 } }, function (bruError, bruResult) {
                                        try {
                                            if (bruError) {

                                                var msg = 'Error in start.js.removesupplementalfromarequest(). bruError: ' + bruError;
                                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                                var source = 'start.js.removesupplementalfromarequest()';
                                                var errorCode = null;
                                                WriteToErrorLog(threatLevel, source, errorCode, msg);

                                                var result = {
                                                    status: 'ERROR',
                                                    message: msg
                                                }
                                                response.send(result);

                                            } else {

                                                //
                                                // Log this in the organization log.
                                                //
                                                var guid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
                                                    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
                                                    return v.toString(16);
                                                });
                                                var ipAddressString = request.headers['x-forwarded-for'] || request.connection.remoteAddress || request.socket.remoteAddress || request.connection.socket.remoteAddress;

                                                var description = 'User has removed a supplemental [' + supplemental_bwBudgetRequestId + '] from request [' + master_bwBudgetRequestId + '].';

                                                var bwOrganizationEvents = new BwOrganizationEvents({
                                                    bwOrganizationEventsId: guid,
                                                    bwWorkflowAppId: bwWorkflowAppId_LoggedIn,
                                                    Description: description,
                                                    //Description_Html: '',
                                                    //Description_Json: xx,
                                                    EventType: 'SUPPLEMENTAL_REMOVED',
                                                    EventSubType: 'SUPPLEMENTAL_REMOVED',
                                                    Created: new Date(),
                                                    CreatedById: bwParticipantId_LoggedIn,
                                                    CreatedByEmail: bwParticipantEmail,
                                                    CreatedByFriendlyName: bwParticipantFriendlyName,
                                                    CreatedByIpAddress: ipAddressString
                                                });
                                                bwOrganizationEvents.save(function (oesError) {
                                                    try {
                                                        if (oesError) {

                                                            var msg = 'Error in start.js.removesupplementalfromarequest():3-3: ' + oesError;
                                                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                                            var source = 'start.js.removesupplementalfromarequest()';
                                                            var errorCode = null;
                                                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                                                            var result = {
                                                                status: 'ERROR',
                                                                message: msg
                                                            }
                                                            response.send(result);

                                                        } else {

                                                            var result = {
                                                                status: 'SUCCESS',
                                                                message: 'SUCCESS'
                                                            };
                                                            response.send(result);

                                                        }

                                                    } catch (e) {

                                                        var msg = 'Exception in start.js.removesupplementalfromarequest():4-4: ' + e.message + ', ' + e.stack;
                                                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                                        var source = 'start.js.removesupplementalfromarequest()';
                                                        var errorCode = null;
                                                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                                                        var result = {
                                                            status: 'EXCEPTION',
                                                            message: msg
                                                        }
                                                        response.send(result);

                                                    }
                                                });

                                            }

                                        } catch (e) {

                                            var msg = 'Exception in start.js.removesupplementalfromarequest():2: ' + e.message + ', ' + e.stack;
                                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                            var source = 'start.js.removesupplementalfromarequest()';
                                            var errorCode = null;
                                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                                            var result = {
                                                status: 'EXCEPTION',
                                                message: msg
                                            }
                                            response.send(result);

                                        }

                                    });

                                }

                            } catch (e) {

                                var msg = 'Exception in start.js.removesupplementalfromarequest():2: ' + e.message + ', ' + e.stack;
                                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.removesupplementalfromarequest()';
                                var errorCode = null;
                                WriteToErrorLog(threatLevel, source, errorCode, msg);

                                var result = {
                                    status: 'EXCEPTION',
                                    message: msg
                                }
                                response.send(result);

                            }

                        });

                    }

                } else {

                    // UNAUTHORIZED.
                    console.log('UNAUTHORIZED in /removesupplementalfromarequest().');
                    console.log('UNAUTHORIZED');
                    console.log('UNAUTHORIZED');
                    response.status(401);
                    response.send(result);

                }

            } catch (e) {

                var msg = 'Exception in start.js.removesupplementalfromarequest():3: ' + e.message + ', ' + e.stack;
                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                var source = 'start.js.removesupplementalfromarequest()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

                var result = {
                    message: msg,
                    status: 'EXCEPTION'
                }
                response.send(result);

            }

        }).catch(function (e) {

            var msg = 'Exception in start.js.removesupplementalfromarequest():2: ' + e;
            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
            var source = 'start.js.removesupplementalfromarequest()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

            var result = {
                message: msg,
                status: 'EXCEPTION'
            }
            response.send(result);

        });

    } catch (e) {

        var msg = 'Exception in start.js.removesupplementalfromarequest(): ' + e.message + ', ' + e.stack;
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.removesupplementalfromarequest()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        var result = {
            status: 'EXCEPTION',
            message: msg
        }
        response.send(result);

    }

});












