router.post('/_bw/bwrecurringexpense/getrelatedbudgetrequests', function (request, response) {
    try {
        var bwRecurringExpenseId = request.body.bwRecurringExpenseId;

        console.log('In bwrecurringexpense/getrelatedbudgetrequests. bwRecurringExpenseId: ' + bwRecurringExpenseId);

        BwRecurringExpense.find({
            bwRecurringExpenseId: bwRecurringExpenseId
        }, function (reError, reResult) {
            if (reError) {
                var msg = 'Error in GET /bwrecurringexpense/getrelatedbudgetrequests:1: ' + reError;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.GET.bwrecurringexpense/getrelatedbudgetrequests()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var results = { message: msg };
                response.send(msg);
            } else {

                console.log('bwrecurringexpense/getrelatedbudgetrequests, reResult.length: ' + reResult.length);

                if (reResult.length == 0) {
                    console.log('Error in POST bwrecurringexpense/getrelatedbudgetrequests(): Could not find the recurring expense.');
                    response.send('Error: Could not find the recurring expense.');

                } else {
                    var projectTitle = reResult[0].ProjectTitle;
                    var title = reResult[0].Title;

                    console.log('bwrecurringexpense/getrelatedbudgetrequests(): ProjectTitle: ' + projectTitle + ' Title: ' + title + '.');


                    // Now we have to get the budget requests.
                    BwBudgetRequest.find({
                        IsRecurringExpense: 'true', RelatedRecurringExpenseId: bwRecurringExpenseId, TrashBin: { $ne: true }
                    }, function (brError, brResult) {
                        if (brError) {
                            var msg = 'Error in POST bwrecurringexpense/getrelatedbudgetrequests:2: ' + brError;
                            // Exception section:
                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.POST.bwrecurringexpense/getrelatedbudgetrequests()';
                            var errorCode = null;
                            var message = msg;
                            WriteToErrorLog(threatLevel, source, errorCode, message);
                            //
                            //var results = { message: msg };
                            response.send(msg);
                        } else {

                            console.log('bwrecurringexpense/getrelatedbudgetrequests(): Found ' + brResult.length + ' related budget requests.');


                            var arraySize = brResult.length;
                            var budgetRequests = [];
                            budgetRequests = new Array(arraySize);
                            for (var i = 0; i < brResult.length; i++) { // doesn't need wrap.
                                var budgetRequest = {
                                    ProjectTitle: brResult[i].ProjectTitle,
                                    Title: brResult[i].Title,
                                    BudgetWorkflowStatus: brResult[i].BudgetWorkflowStatus,
                                    Modified: brResult[i].Modified,
                                    ModifiedByFriendlyName: brResult[i].ModifiedByFriendlyName
                                };
                                budgetRequests[i] = budgetRequest;
                            }

                            var result = {
                                RecurringExpense: reResult,
                                //ProjectTitle: projectTitle,
                                //Title: title,
                                BudgetRequests: budgetRequests
                            };

                            response.send(result);
                        }
                    });
                }
            }
        });
    } catch (e) {
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.bwrecurringexpense/getrelatedbudgetrequests()';
        var errorCode = null;
        var message = e.message;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        response.send('Error in POST bwrecurringexpense/getrelatedbudgetrequests: ' + e.message);
    }
});









