                        var msg = 'Error in DELETE /bwquoterequestsdataset:1: ' + sError;
                        // Exception section:
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.DELETE.bwquoterequestsdataset()';
                        var errorCode = null;
