function updateUserDetailsForBwWorkflowAppId(bwWorkflowAppId, bwParticipantId, bwParticipantFriendlyName, bwParticipantEmail, modifiedById, modifiedByFriendlyName, modifiedByEmail, recordCount) {
    //function synchronizeParticipantOrgRolesxxxxx(rolesJson, orgId, bwTenantId, bwWorkflowAppId, modifiedById, modifiedByFriendlyName, modifiedByEmail, divisionIndex, groupIndex, entityIndex, locationIndex) {
    return new Promise(function (resolve, reject) {
        try {
            console.log('In updateUserDetailsForBwWorkflowAppId(). bwWorkflowAppId: ' + bwWorkflowAppId + ', recordCount: ' + recordCount);

            BwOrgRoles.find({
                bwWorkflowAppId: bwWorkflowAppId, bwOrgRolesActive: true
            }, function (orfError, orfResult) {
                try {
                    if (orfError) {

                        var msg = 'Error in start.js.updateUserDetailsForBwWorkflowAppId:' + orfError;
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.GET.updateUserDetailsForBwWorkflowAppId()';
                        var errorCode = null;
                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                        var result = {
                            result: 'Error',
                            message: msg
                        }
                        resolve(result);

                    } else {

                        if (orfResult.length != 1) {
                            // Unexpected value.
                            var msg = 'Error in updateUserDetailsForBwWorkflowAppId(). Unexpected length value for BwOrgRoles.find(). bwWorkflowAppId: ' + bwWorkflowAppId + ', orfResult.length: ' + orfResult.length;

                            var result = {
                                result: 'Error',
                                message: msg
                            }
                            resolve(result);

                        } else {

                            var json = JSON.parse(orfResult[0].bwOrgRolesJson);
                            // Go through the json checking every "Roles" node.
                            var participantExistsAlready = false;
                            var participantExistsMessage = '';
                            if (json.Global && json.Global.Roles) {
                                for (var i = 0; i < json.Global.Roles.length; i++) {
                                    if (json.Global.Roles[i].ParticipantId == bwParticipantId) {
                                        json.Global.Roles[i].ParticipantFriendlyName = bwParticipantFriendlyName;
                                        json.Global.Roles[i].ParticipantEmail = bwParticipantEmail;
                                        participantExistsAlready = true;
                                        participantExistsMessage += 'Participant user details updated at json.Global.Roles[' + i + '].';
                                    }
                                }
                            }
                            if (json.Global && json.Global.Divisions) {
                                for (var d = 0; d < json.Global.Divisions.Items.length; d++) {
                                    if (json.Global.Divisions.Items[d].Roles) {
                                        for (var i = 0; i < json.Global.Divisions.Items[d].Roles.length; i++) {
                                            if (json.Global.Divisions.Items[d].Roles[i].ParticipantId == bwParticipantId) {
                                                json.Global.Divisions.Items[d].Roles[i].ParticipantFriendlyName = bwParticipantFriendlyName;
                                                json.Global.Divisions.Items[d].Roles[i].ParticipantEmail = bwParticipantEmail;
                                                participantExistsAlready = true;
                                                participantExistsMessage += 'Participant user details updated at json.Global.Divisions.Items[' + d + '].Roles[' + i + '].';
                                            }
                                        }
                                    }
                                    for (var g = 0; g < json.Global.Divisions.Items[d].Groups.Items.length; g++) {
                                        if (json.Global.Divisions.Items[d].Groups.Items[g].Roles) {
                                            for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].Roles.length; i++) {
                                                if (json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].ParticipantId == bwParticipantId) {
                                                    json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].ParticipantFriendlyName = bwParticipantFriendlyName;
                                                    json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].ParticipantEmail = bwParticipantEmail;
                                                    participantExistsAlready = true;
                                                    participantExistsMessage += 'Participant user details updated at json.Global.Divisions.Items[' + d + '].Groups.Items[' + g + '].Roles[' + i + '].';
                                                }
                                            }
                                        }
                                        for (var e = 0; e < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items.length; e++) {
                                            if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles) {
                                                for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles.length; i++) {
                                                    if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].ParticipantId == bwParticipantId) {
                                                        json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].ParticipantFriendlyName = bwParticipantFriendlyName;
                                                        json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].ParticipantEmail = bwParticipantEmail;
                                                        participantExistsAlready = true;
                                                        participantExistsMessage += 'Participant user details updated at json.Global.Divisions.Items[' + d + '].Groups.Items[' + g + '].LegalEntities.Items[' + e + '].Roles[' + i + '].';
                                                    }
                                                }
                                            }
                                            for (var l = 0; l < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items.length; l++) {
                                                if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles) {
                                                    for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles.length; i++) {
                                                        if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].ParticipantId == bwParticipantId) {
                                                            json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].ParticipantFriendlyName = bwParticipantFriendlyName;
                                                            json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].ParticipantEmail = bwParticipantEmail;
                                                            participantExistsAlready = true;
                                                            participantExistsMessage += 'Participant user details updated at json.Global.Divisions.Items[' + d + '].Groups.Items[' + g + '].LegalEntities.Items[' + e + '].Locations.Items[' + l + '].Roles[' + i + '].';
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            //console.log('>>>>>>>> In updateUserDetailsForBwWorkflowAppId(). participantExistsMessage: ' + participantExistsMessage);

                            // Now we have to save it back to the database.
                            var timestamp = new Date();
                            BwOrgRoles.update({
                                bwOrgRolesId: orfResult[0].bwOrgRolesId
                            }, {
                                Modified: timestamp, ModifiedById: modifiedById, ModifiedByFriendlyName: modifiedByFriendlyName, ModifiedByEmail: modifiedByEmail, bwOrgRolesJson: JSON.stringify(json)
                            }, function (oruError, oruMod) {
                                try {
                                    if (oruError) {

                                        var msg = 'Error in start.js.updateUserDetailsForBwWorkflowAppId.BwOrgRoles.update(). bwOrgRolesId: ' + orfResult[0].bwOrgRolesId + ', ' + oruError;
                                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                        var source = 'start.js.GET.updateUserDetailsForBwWorkflowAppId()';
                                        var errorCode = null;
                                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                                        var result = {
                                            result: 'Error',
                                            message: msg
                                        }
                                        resolve(result);

                                    } else {

                                        // Done.
                                        var result = {
                                            result: 'SUCCESS',
                                            bwWorkflowAppId: bwWorkflowAppId,
                                            mod: oruMod,
                                            recordCount: recordCount,
                                            message: participantExistsMessage
                                        }
                                        resolve(result);

                                    }
                                } catch (e) {

                                    var msg = 'Exception in updateUserDetailsForBwWorkflowAppId():3: ' + e.message + ', ' + e.stack;
                                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.updateUserDetailsForBwWorkflowAppId()';
                                    var errorCode = null;
                                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                                    var result = {
                                        message: msg,
                                        InnerException: e
                                    }
                                    reject(result);

                                }
                            });

                        }
                    }
                } catch (e) {

                    var msg = 'Exception in updateUserDetailsForBwWorkflowAppId():2: ' + e.message + ', ' + e.stack;
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.updateUserDetailsForBwWorkflowAppId()';
                    var errorCode = null;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                    var result = {
                        message: msg,
                        InnerException: e
                    }
                    reject(result);

                }
            });

        } catch (e) {

            var msg = 'Exception in updateUserDetailsForBwWorkflowAppId(): ' + e.message + ', ' + e.stack;
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js.updateUserDetailsForBwWorkflowAppId()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg);

            var result = {
                message: msg,
                InnerException: e
            }
            reject(result);

        }
    });
}


