router.post('/_bw/bwworkflow/itemizeparticipantdependencies', function (request, response) {
    try {
        var bwParticipantId = request.body.bwParticipantId;
        var bwWorkflowAppId = request.body.bwWorkflowAppId;

        if (!(bwWorkflowAppId && bwParticipantId)) {

            var msg = 'In itemizeparticipantdependencies(). Cannot proceed, invalid value(s) for bwWorkflowAppId: ' + bwWorkflowAppId + ', bwParticipantId: ' + bwParticipantId;
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js.POST.bwworkflow/itemizeparticipantdependencies()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg);

            //var results = { message: msg };
            response.send(msg);

        } else {

            BwOrgRoles.find({
                bwWorkflowAppId: bwWorkflowAppId, bwOrgRolesActive: true
            }, function (orfError, orfResult) {
                try {
                    if (orfError) {

                        var msg = 'Error in start.js.updateUserDetailsForBwWorkflowAppId:' + orfError;
                        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.GET.updateUserDetailsForBwWorkflowAppId()';
                        var errorCode = null;
                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                        //var results = { message: msg };
                        response.send(msg);

                    } else {

                        if (orfResult.length != 1) {
                            // Unexpected value.
                            var msg = 'Error in updateUserDetailsForBwWorkflowAppId(). Unexpected length value for BwOrgRoles.find(). bwWorkflowAppId: ' + bwWorkflowAppId + ', orfResult.length: ' + orfResult.length;

                            //var results = { message: msg };
                            response.send(msg);

                        } else {

                            var json = JSON.parse(orfResult[0].bwOrgRolesJson);

                            // Go through the json getting every "Roles" node for bwParticipantId.
                            var participantOrgRolesCount = 0;
                            if (json.Global && json.Global.Roles) {
                                for (var i = 0; i < json.Global.Roles.length; i++) {
                                    if (json.Global.Roles[i].ParticipantId == bwParticipantId) {
                                        participantOrgRolesCount += 1;
                                    }
                                }
                            }
                            if (json.Global && json.Global.Divisions) {
                                for (var d = 0; d < json.Global.Divisions.Items.length; d++) {
                                    if (json.Global.Divisions.Items[d].Roles) {
                                        for (var i = 0; i < json.Global.Divisions.Items[d].Roles.length; i++) {
                                            if (json.Global.Divisions.Items[d].Roles[i].ParticipantId == bwParticipantId) {
                                                participantOrgRolesCount += 1;
                                            }
                                        }
                                    }
                                    for (var g = 0; g < json.Global.Divisions.Items[d].Groups.Items.length; g++) {
                                        if (json.Global.Divisions.Items[d].Groups.Items[g].Roles) {
                                            for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].Roles.length; i++) {
                                                if (json.Global.Divisions.Items[d].Groups.Items[g].Roles[i].ParticipantId == bwParticipantId) {
                                                    participantOrgRolesCount += 1;
                                                }
                                            }
                                        }
                                        for (var e = 0; e < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items.length; e++) {
                                            if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles) {
                                                for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles.length; i++) {
                                                    if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Roles[i].ParticipantId == bwParticipantId) {
                                                        participantOrgRolesCount += 1;
                                                    }
                                                }
                                            }
                                            for (var l = 0; l < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items.length; l++) {
                                                if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles) {
                                                    for (var i = 0; i < json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles.length; i++) {
                                                        if (json.Global.Divisions.Items[d].Groups.Items[g].LegalEntities.Items[e].Locations.Items[l].Roles[i].ParticipantId == bwParticipantId) {
                                                            participantOrgRolesCount += 1;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }

                            BwFunctionalArea.find({
                                bwWorkflowAppId: bwWorkflowAppId, $or: [{
                                    Approver1Id: bwParticipantId
                                }, {
                                    Approver2Id: bwParticipantId
                                }, {
                                    Approver3Id: bwParticipantId
                                }, {
                                    Approver4Id: bwParticipantId
                                }, {
                                    Approver5Id: bwParticipantId
                                }, {
                                    Approver6Id: bwParticipantId
                                }, {
                                    Approver7Id: bwParticipantId
                                }, {
                                    Approver8Id: bwParticipantId
                                }, {
                                    Approver9Id: bwParticipantId
                                }, {
                                    Approver10Id: bwParticipantId
                                }]
                            }, function (faError, faResult) {
                                if (!faError) {
                                    BwWorkflowTask.find({
                                        bwWorkflowAppId: bwWorkflowAppId, bwAssignedToId: bwParticipantId, bwPercentComplete: 0, TaskType: 'BUDGET_REQUEST_WORKFLOW_TASK', TrashBin: { $ne: true }
                                    }, function (wtError, wtResult) {
                                        if (!wtError) {
                                            // We can get a list Budget Requests by looking for incomplete ones.
                                            // WE ARE NOT RETURNING ONLY INCOMPLETE BRs, WE ARE RETURNING ALL OF THEM!!!! Todd: fix this.
                                            BwBudgetRequest.find({
                                                bwWorkflowAppId: bwWorkflowAppId, ARStatus: 'Submitted', ManagerId: bwParticipantId, TrashBin: { $ne: true }
                                            }, function (brError, brResult) {
                                                if (!brError) {
                                                    var results = {
                                                        NumberOfOrganizationRoles: participantOrgRolesCount, NumberOfFunctionalAreas: faResult.length, NumberOfIncompleteTasks: wtResult.length, NumberOfIncompleteBudgetRequestsSpecifiedAsManager: brResult.length, message: 'SUCCESS'
                                                    };
                                                    response.send(results);
                                                } else {
                                                    var msg = 'Error in /bwworkflow/itemizeparticipantdependencies: ' + brError;
                                                    // Exception section:
                                                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                                    var source = 'start.js.POST.bwworkflow/itemizeparticipantdependencies()';
                                                    var errorCode = null;
                                                    var message = msg;
                                                    WriteToErrorLog(threatLevel, source, errorCode, message);
                                                    //
                                                    //var results = { message: msg };
                                                    response.send(msg);
                                                }
                                            });
                                        } else {
                                            var msg = 'Error in /bwworkflow/itemizeparticipantdependencies: ' + wtError;
                                            // Exception section:
                                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                            var source = 'start.js.POST.bwworkflow/itemizeparticipantdependencies()';
                                            var errorCode = null;
                                            var message = msg;
                                            WriteToErrorLog(threatLevel, source, errorCode, message);
                                            //
                                            //var results = { message: msg };
                                            response.send(msg);
                                        }
                                    });
                                } else {
                                    var msg = 'Error in /bwworkflow/itemizeparticipantdependencies: ' + faError;
                                    // Exception section:
                                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.POST.bwworkflow/itemizeparticipantdependencies()';
                                    var errorCode = null;
                                    var message = msg;
                                    WriteToErrorLog(threatLevel, source, errorCode, message);
                                    //
                                    //var results = { message: msg };
                                    response.send(msg);
                                }
                            });

                        }
                    }
                } catch (e) {

                    var msg = 'Exception in POST /bwworkflow/itemizeparticipantdependencies:2:' + e.message;
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.POST.bwworkflow/itemizeparticipantdependencies()';
                    var errorCode = null;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                    //var results = { message: msg };
                    response.send(msg);

                }
            });

        }

    } catch (e) {

        var msg = 'Exception in POST /bwworkflow/itemizeparticipantdependencies:' + e.message;
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.bwworkflow/itemizeparticipantdependencies()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        //var results = { message: msg };
        response.send(msg);

    }
});







