router.post('/_bw/bwworkflow/checkValidityOfPasswordResetIdentifier', function (request, response) {
    try {
        var passwordResetIdentifier = request.body.passwordResetIdentifier;
        // bwParticipantPlaceholder2 - This stores the "passwordreset" guid that we use in the email link.
        // bwParticipantPlaceholder3 - This stores the "passwordreset" X-FORWARDED-FOR string that was gotten when the password reset was requested. This ensures the user uses the same computer and location when resetting their password.
        // bwParticipantPlaceholder4 - This stores the "passwordreset" created timestamp. This allows us to expire the passwordreset in 5 minutes.
        var ipAddressString = request.headers['x-forwarded-for'] || request.connection.remoteAddress || request.socket.remoteAddress || request.connection.socket.remoteAddress;
        var modified = new Date(); // Converted from getCreatedTimestamp(); 2-6-2022
        BwParticipant.find({
            bwParticipantPlaceholder2: passwordResetIdentifier
        }, function (pError, pResult) {
            if (!pError) {
                if (pResult.length > 0) {
                    // The passwordResetIdentifier exists.
                    var passwordResetCreatedTimestamp = pResult[0].bwParticipantPlaceholder4;
                    // Now figure out if the request has gone past 5 minutes and expired.
                    var elapsedTimeSinceCreated = 0;
                    try {
                        var date = passwordResetCreatedTimestamp.split('T')[0];
                        var year = date.split('-')[0];
                        var month = date.split('-')[1];
                        var day = date.split('-')[2];
                        //
                        var time = passwordResetCreatedTimestamp.split('T')[1];
                        var hour = time.split(':')[0];
                        var minute = time.split(':')[1];
                        var second = time.split(':')[2];
                        //
                        var tmpPasswordResetCreatedTimestamp = new Date(Number(year), Number(month) - 1, Number(day), Number(hour), Number(minute), Number(second));
                        var currentTime = new Date(); //.getTime();
                        //
                        elapsedTimeSinceCreated = Math.floor((currentTime - tmpPasswordResetCreatedTimestamp) / 60000); // This is in minutes!

                        console.log('tmpPasswordResetCreatedTimestamp: ' + tmpPasswordResetCreatedTimestamp);
                        console.log('currentTime: ' + currentTime);
                        console.log('elapsedTimeSinceCreated: ' + elapsedTimeSinceCreated);

                    } catch (e) {
                        // TODD: THIS NEEDS TO BE REEXAMINED, we are catching this error when the new recurring tasks cam einto play!
                        //thisMustBeADifferentKindOfTask = true;
                        console.log('Error calculating elapsed time: ' + e.message);
                    }

                    if (elapsedTimeSinceCreated > 5) {
                        // Greater than 5 minutes.
                        var result = {
                            message: 'EXPIRED PASSWORDRESET ID'
                        };
                        response.send(result);
                    } else {
                        // Check if coming from the same device.
                        var xForwardedFor = pResult[0].bwParticipantPlaceholder3;
                        if (xForwardedFor != ipAddressString) {
                            // They don't match!
                            var result = {
                                message: 'INVALID PASSWORDRESET DEVICEORLOCATION'
                            };
                            response.send(result);
                        } else {
                            // Everything is Ok!
                            var result = {
                                message: 'VALID PASSWORDRESET'
                            };
                            response.send(result);
                        }
                    }
                } else {
                    // The passwordResetIdentifier does not exist.
                    var result = {
                        message: 'INVALID PASSWORDRESET ID'
                    };
                    response.send(result);
                }
            } else {
                var msg = 'Error in POST /bwworkflow/checkValidityOfPasswordResetIdentifier:1: ' + pError;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.POST.bwworkflow/checkValidityOfPasswordResetIdentifier()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                var result = {
                    message: msg
                };
                response.send(result);
            }
        });
    } catch (e) {
        var msg = 'Error in POST /bwworkflow/checkValidityOfPasswordResetIdentifier:2: ' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.bwworkflow/checkValidityOfPasswordResetIdentifier()';
        var errorCode = null;
        var message = msg;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        var result = {
            message: msg
        };
        response.send(result);
    }
});













