router.get('/_bw/getallinventory/:bwWorkflowAppId', function (request, response) {
    try {
        console.log('In getallinventory(). Returning all of the inventory items to the client.');

        var bwWorkflowAppId = request.params.bwWorkflowAppId;

        BwInventoryItem.find({ bwWorkflowAppId: bwWorkflowAppId }, null, {}, function (err, result) {
            if (err) {
                console.log(err);
                response.send(err);
            } else {
                response.send(result);
            }
        });

    } catch (e) {
        console.log('Exception in getallinventory(): ' + e.message + ', ' + e.stack);
        response.send('Exception in GET /getallinventory:' + e.message + ', ' + e.stack);
    }
});

router.post('/_bw/saveinventoryitem', function (request, response) {
    try {
        console.log('In start.js.saveinventoryitem().');

        var bwTenantId = request.body.bwTenantId;
        var bwWorkflowAppId = request.body.bwWorkflowAppId;
        var bwInventoryItemId = request.body.bwInventoryItemId;

        var Title = request.body.Title;
        var ProductCode = request.body.ProductCode;
        var Description = request.body.Description;
        var ExtendedDescription = request.body.ExtendedDescription;
        var Price = request.body.Price;

        var Segment = request.body.Segment;
        var Subclass = request.body.Subclass;

        var bwParticipantId = request.body.bwParticipantId;
        var bwParticipantEmail = request.body.bwParticipantEmail;
        var bwParticipantFriendlyName = request.body.bwParticipantFriendlyName;
        var timestamp = new Date();

        console.log('In saveInventoryItem(). Updating request bwWorkflowAppId: ' + bwWorkflowAppId + ', bwInventoryItemId: ' + bwInventoryItemId);


        BwInventoryItem.find({ bwWorkflowAppId: bwWorkflowAppId, bwInventoryItemId: bwInventoryItemId }, function (iifError, iifResult) {
            if (iifError) {

                var msg = 'Error in start.js.saveinventoryitem.BwInventoryItem.find(): ' + iifError;
                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                var source = 'start.js.saveinventoryitem()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg);
                //
                //var results = { message: msg };
                //console.log(msg);
                var result = {
                    message: msg
                }
                response.send(result);

            } else {

                if (iifResult.length == 1) {

                    // UPDATE
                    BwInventoryItem.update({
                        bwWorkflowAppId: bwWorkflowAppId, bwInventoryItemId: bwInventoryItemId
                    }, {
                        Title: Title, ProductCode: ProductCode, Description: Description, ExtendedDescription: ExtendedDescription, Price: Price, Segment: Segment, Subclass: Subclass, ModifiedById: bwParticipantId, ModifiedByFriendlyName: bwParticipantFriendlyName, ModifiedByEmail: bwParticipantEmail, Modified: timestamp
                    }, function (error, mod) {
                        if (!error) {
                            console.log('SUCCESS: data: ' + JSON.stringify(request.body) + ', mod: ' + JSON.stringify(mod));

                            var modifiedCount = 0;
                            if (mod.hasOwnProperty('modifiedCount')) {
                                modifiedCount = mod.modifiedCount;
                            } else if (mod.hasOwnProperty('nModified')) {
                                modifiedCount = mod.nModified;
                            }

                            //if (!mod.hasOwnProperty('modifiedCount')) {
                            //    throw new Error('xcx123423423-8 Object missing property "modifiedCount".');
                            //}

                            if (modifiedCount == 1) {

                                var results = {
                                    message: 'SUCCESS',
                                    mod: mod,
                                    data: request.body
                                }
                                response.send(results);

                            } else {

                                var results = {
                                    message: 'Unexpected response: ' + JSON.stringify(mod),
                                    mod: mod,
                                    data: request.body
                                }
                                response.send(results);

                            }

                        } else {

                            var msg = 'Error in start.js.saveInventoryItem(): ' + error;
                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.saveInventoryItem()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            //var result = { message: msg };
                            //response.send(msg);

                            var results = {
                                message: msg,
                                mod: '',
                                data: request.body
                            }
                            response.send(results);

                        }
                    });

                } else if (iifResult.length == 0) {

                    // SAVE
                    var bwInventoryItem = new BwInventoryItem(
                        {
                            bwTenantId: bwTenantId,
                            bwWorkflowAppId: bwWorkflowAppId,
                            bwInventoryItemId: bwInventoryItemId,
                            Title: Title,
                            ProductCode: ProductCode,
                            Description: Description,
                            ExtendedDescription: ExtendedDescription,
                            Price: Price,
                            CreatedById: bwParticipantId,
                            CreatedByFriendlyName: bwParticipantFriendlyName,
                            CreatedByEmail: bwParticipantEmail,
                            Created: timestamp
                        });
                    bwInventoryItem.save(function (error, mod) {
                        if (error) {

                            var msg = 'Error in start.js.saveinventoryitem(). mod: ' + JSON.stringify(mod);
                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.saveinventoryitem()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            var result = {
                                message: msg
                            }
                            response.send(result);

                        } else {


                            writeTimerLogEntry('ADDED NEW inventory item mod: ' + JSON.stringify(mod));
                            var result = {
                                message: 'SUCCESS',
                                result: {
                                    mod: JSON.stringify(mod)
                                }
                            }
                            response.send(result);

                        }
                    });


                } else {

                    // Unexpected results return error.
                    var msg = 'Error in saveInventoryItem(). Unexpected value for iifResult: ' + JSON.stringify(iifResult);
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.saveinventoryitem()';
                    var errorCode = null;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                    var result = {
                        message: msg,
                        TheLastOne: theLastOne
                    }
                    response.send(result);

                }
            }
        });

    } catch (e) {

        var msg = 'Exception in start.js.saveInventoryItem(): ' + e.message + ', ' + e.stack;
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.saveinventoryitem()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        //var result = { message: msg };
        response.send(msg);

    }
});










