router.post('/_bw/bwparticipant/updateuserconfigurationbehaviorselectednotificationsound', function (request, response) {
    try {
        console.log('In bwparticipant/updateuserconfigurationbehaviorselectednotificationsound().');

        var expectedSounds = ['nosound', 'random', 'starpulse', 'cashregister', 'crickets'];

        var bwWorkflowAppId = request.body.bwWorkflowAppId;
        var bwParticipantId = request.body.bwParticipantId;

        var selectedSound = request.body.selectedSound;

        if (!bwWorkflowAppId || !bwParticipantId) {

            var msg = 'Error in updateuserconfigurationbehaviorselectednotificationsound(). Unexpected value(s) for bwWorkflowAppId: ' + bwWorkflowAppId + ', bwParticipantId: ' + bwParticipantId;
            var result = {
                status: 'ERROR',
                message: msg
            }

            response.send(result);

        } else {

            if (!(expectedSounds.indexOf(selectedSound) > -1)) {

                var msg = 'Error in updateuserconfigurationbehaviorselectednotificationsound(). Unexpected value(s) for selectedSound: ' + selectedSound;
                var result = {
                    status: 'ERROR',
                    message: msg
                }

                response.send(result);

            } else {

                BwParticipant.update({ bwParticipantId: bwParticipantId }, { bwSelectedNotificationSound: selectedSound, Modified: new Date() }, function (error, mod) {
                    try {
                        if (error) {

                            var msg = 'Error updating the participant xcx312423-21. ' + bwParticipantId + ': ' + error + ', ' + JSON.stringify(mod);
                            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.bwparticipant/updateuserconfigurationbehaviorselectednotificationsound()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            var result = {
                                status: 'ERROR',
                                message: msg
                            };
                            response.send(result);

                        } else {

                            var result = {
                                status: 'SUCCESS',
                                message: 'SUCCESS'
                            };
                            response.send(result);

                        }

                    } catch (e) {

                        var msg = 'Exception in start.js.bwparticipant/updateuserconfigurationbehaviorselectednotificationsound:2: ' + e.message + ', ' + e.stack;
                        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.bwparticipant/updateuserconfigurationbehaviorselectednotificationsound()';
                        var errorCode = null;
                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                        var result = {
                            status: 'EXCEPTION',
                            message: msg
                        };
                        response.send(result);

                    }
                });

            }
        }
    } catch (e) {

        var msg = 'Exception in start.js.bwparticipant/updateuserconfigurationbehaviorselectednotificationsound: ' + e.message + ', ' + e.stack;
        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
        var source = 'start.js.bwparticipant/updateuserconfigurationbehaviorselectednotificationsound()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        var result = {
            status: 'EXCEPTION',
            message: msg
        };
        response.send(result);

    }
});

