router.put('/_bw/participants/invite', function (request, response) {
    try {
        var bwInvitationParticipantRole = request.body.bwInvitationParticipantRole;
        // Since we are creating this, we will create a unique GUID Participant Id.
        var invitationId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
            var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
        var bwInvitation = new BwInvitation(
            {
                bwInvitationId: invitationId,
                bwTenantId: request.body.bwTenantId,
                bwWorkflowAppId: request.body.bwWorkflowAppId,
                bwWorkflowAppTitle: request.body.bwWorkflowAppTitle,
                bwInvitationParticipantRole: bwInvitationParticipantRole,
                bwInvitationCreatedById: request.body.bwInvitationCreatedById,
                bwInvitationCreatedByFriendlyName: request.body.bwInvitationCreatedByFriendlyName,
                bwInvitationCreatedByEmail: request.body.bwInvitationCreatedByEmail,
                bwInvitationCreatedTimestamp: request.body.bwInvitationCreatedTimestamp,
                bwInvitationAcceptedById: '-1' // This facilitates our mongo find() query.
            });
        bwInvitation.save(function (error) {
            if (!error) {
                console.log('In participants/invite(). Saved BwInvitation: ' + JSON.stringify(bwInvitation));

                response.send(invitationId);
            } else {
                var msg = 'Error in PUT /participants/invite:1: ' + error;
                // Exception section:
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js.PUT.participants/invite()';
                var errorCode = null;
                var message = msg;
                WriteToErrorLog(threatLevel, source, errorCode, message);
                //
                //var result = { message: msg };
                response.send(msg);
            }
        });
    } catch (e) {
        var msg = 'Error in PUT /participants/invite:2: ' + e.message;
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.PUT.participants/invite()';
        var errorCode = null;
        var message = msg;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        //var result = { message: msg };
        response.send(msg);
    }
});

