router.post('/_bw/bwtenant/deregister', function (request, response) {
    // This method is called from the admin interface. Note that it may leave workflow app information orphaned, as I have not vetted it completely. This method is a bit rough around the edges.
    try {
        console.log('In bwtenant/deregister().');

        var bwParticipantId_LoggedIn = request.body.bwParticipantId_LoggedIn;
        var bwActiveStateIdentifier = request.body.bwActiveStateIdentifier;
        var bwWorkflowAppId_LoggedIn = request.body.bwWorkflowAppId_LoggedIn;

        var promise = AuthorizeWebServiceCall(request, bwParticipantId_LoggedIn, bwActiveStateIdentifier, bwWorkflowAppId_LoggedIn, 'Forest Administrator');
        promise.then(function (result) {
            try {

                if (result.status == 'AUTHORIZED') {

                    // AUTHORIZED.
                    console.log('AUTHORIZED in /bwtenant/deregister().');
                    console.log('AUTHORIZED');
                    console.log('AUTHORIZED');

                    //
                    // Step 1: Find the BwTenant with the { bwTenantId: bwTenantId, bwTenantOwnerId: bwTenantOwnerId, tenantOwnerEmail: tenantOwnerEmail }
                    //  - If we find this, we can safetly chane the bwParticipantEmail her, and also in the BwParticipant table.
                    //    - Rename as follows, for example: "todd2@budgetworkflow.com@SYSTEMDEREGISTER_1". Increment the trailing number. DEV: Keep an eye to see when this is finished 100%.
                    //

                    var bwTenantId = request.body.bwTenantId;
                    //var bwTenantOwnerId = request.body.bwTenantOwnerId;
                    var bwTenantOwnerEmail = request.body.bwTenantOwnerEmail;

                    BwTenant.find({ bwTenantId: bwTenantId, bwTenantOwnerEmail: bwTenantOwnerEmail }, function (tfError, tfResult) {
                        try {
                            if (tfError) {

                                var msg = 'Error in start.js.deregister(). tfError: ' + tfError;
                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.deregister()';
                                var errorCode = null;
                                WriteToErrorLog(threatLevel, source, errorCode, msg);

                                var result = {
                                    status: 'ERROR',
                                    message: msg
                                };
                                response.send(result);

                            } else {

                                if (!tfResult) {

                                    var msg = 'Error in start.js.deregister(). COULD NOT FIND THE TENANT FOR THIS EMAIL ADDRESS. THIS PROCESS CANNOT CONTINUE.';
                                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js.deregister()';
                                    var errorCode = null;
                                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                                    var result = {
                                        status: 'ERROR',
                                        message: msg
                                    };
                                    response.send(result);

                                } else {

                                    //
                                    // We do a find here so that this checks for multiples. It should never happen, but here we are, checking. 7-25-2024.
                                    //

                                    if (tfResult.length > 1) {

                                        var msg = 'Error in start.js.deregister(). FOUND MULTIPLE TENANTS FOR THIS EMAIL ADDRESS. THIS PROCESS CANNOT CONTINUE.';
                                        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                        var source = 'start.js.deregister()';
                                        var errorCode = null;
                                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                                        var result = {
                                            status: 'ERROR',
                                            message: msg
                                        };
                                        response.send(result);

                                    } else if (tfResult.length == 1) {

                                        //
                                        //
                                        // Ok this checks out. Lets change the email address in the BwTenant and BwParticipant tables. 7-25-2024.
                                        //
                                        // THIS IS WHERE WE DEREGISTER.
                                        //

                                        var deregisteredEmailAddress = bwTenantOwnerEmail + '@SYSTEM_DEREGISTER_07_25_2024_2-21pmadt';

                                        BwTenant.updateOne({ bwTenantId: bwTenantId, bwTenantOwnerEmail: bwTenantOwnerEmail }, { bwTenantOwnerEmail: deregisteredEmailAddress }, function (tuError, tuMod) {
                                            try {
                                                if (tuError) {

                                                    var msg = 'Error in start.js.deregister(). tuError: ' + tuError + ', tuMod: ' + JSON.stringify(tuMod);
                                                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                                    var source = 'start.js.deregister()';
                                                    var errorCode = null;
                                                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                                                    var result = {
                                                        status: 'ERROR',
                                                        message: msg
                                                    };
                                                    response.send(result);

                                                } else {

                                                    BwParticipant.updateOne({ bwTenantId: bwTenantId, bwParticipantEmail: bwTenantOwnerEmail }, { bwParticipantEmail: deregisteredEmailAddress }, function (puError, puMod) {
                                                        try {
                                                            if (puError) {

                                                                var msg = 'Error in start.js.deregister(). puError: ' + puError + ', tuMod: ' + JSON.stringify(puMod);
                                                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                                                var source = 'start.js.deregister()';
                                                                var errorCode = null;
                                                                WriteToErrorLog(threatLevel, source, errorCode, msg);

                                                                var result = {
                                                                    status: 'ERROR',
                                                                    message: msg
                                                                };
                                                                response.send(result);

                                                            } else {

                                                                var msg = 'Successfully deregistered. deregisteredEmailAddress: ' + deregisteredEmailAddress + ', tuMod: ' + JSON.stringify(tuMod) + ', puMod: ' + JSON.stringify(puMod);
                                                                var result = {
                                                                    status: 'SUCCESS',
                                                                    message: msg
                                                                }

                                                                response.send(result);
                                                            }

                                                        } catch (e) {

                                                            var msg = 'Exception in start.js.deregister():6: ' + e.message + ', ' + e.stack;
                                                            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                                            var source = 'start.js.deregister()';
                                                            var errorCode = null;
                                                            WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

                                                            var result = {
                                                                message: msg,
                                                                status: 'EXCEPTION'
                                                            }
                                                            response.send(result);

                                                        }

                                                    });

                                                }

                                            } catch (e) {

                                                var msg = 'Exception in start.js.deregister():5: ' + e.message + ', ' + e.stack;
                                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                                var source = 'start.js.deregister()';
                                                var errorCode = null;
                                                WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

                                                var result = {
                                                    message: msg,
                                                    status: 'EXCEPTION'
                                                }
                                                response.send(result);

                                            }

                                        });

                                    } else {

                                        //var bwTenantId = request.body.bwTenantId;
                                        //var bwTenantOwnerId = request.body.bwTenantOwnerId;
                                        //var bwTenantOwnerEmail = request.body.bwTenantOwnerEmail;

                                        var msg = 'Error in start.js.deregister(). FOUND UNEXPECTED TENANTS.length FOR THIS EMAIL ADDRESS. THIS PROCESS CANNOT CONTINUE. tfResult.length: ' + tfResult.length + ', bwTenantId: ' + bwTenantId + ', bwTenantOwnerId: ' + bwTenantOwnerId + ', bwTenantOwnerEmail: ' + bwTenantOwnerEmail;
                                        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                        var source = 'start.js.deregister()';
                                        var errorCode = null;
                                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                                        var result = {
                                            status: 'ERROR',
                                            message: msg
                                        };
                                        response.send(result);

                                    }

                                }

                            }

                        } catch (e) {

                            var msg = 'Exception in start.js.bwtenant/deregister:xcx2e23444-44: ' + e.message + ', ' + e.stack;
                            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                            var source = 'start.js./bwtenant/deregister()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            var result = {
                                message: msg,
                                status: 'EXCEPTION'
                            }
                            response.send(result);

                        }

                    });

                } else {

                    // UNAUTHORIZED.
                    console.log('UNAUTHORIZED in /bwtenant/deregister().');
                    console.log('UNAUTHORIZED');
                    console.log('UNAUTHORIZED');
                    response.status(401);
                    response.send(result);

                }

            } catch (e) {

                var msg = 'Exception in start.js.bwtenant/deregister:xcx2e23444: ' + e.message + ', ' + e.stack;
                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                var source = 'start.js./bwtenant/deregister()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg);

                var result = {
                    message: msg,
                    status: 'EXCEPTION'
                }
                response.send(result);

            }

        }).catch(function (e) {

            var msg = 'Exception in start.js./bwtenant/deregister():xcx44hj: ' + e;
            var threatLevel = 'high'; // severe, high, elevated, guarded, low.
            var source = 'start.js./bwtenant/deregister()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg);

            var result = {
                message: msg,
                status: 'EXCEPTION'
            }
            response.send(result);

        });

    } catch (e) {

        var msg = 'Exception in start.js./bwtenant/deregister():1: ' + e.message + ', ' + e.stack;
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.bwtenant/deregister()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        var result = {
            message: msg
        }
        response.send(result);

    }
});


