// Moved from bwtaskdataservice 10-21-2022 and copied from cmdNewTasksTimer().
function cmdNewTasksTimer2(bwWorkflowAppId) {
    try {
        console.log('cmdNewTasksTimer2(). bwWorkflowAppId: ' + bwWorkflowAppId);
        //
        // This gets launched when the workflow gets to a certain stage. This keeps New Tasks from stalling the workflow, when the Timers are not running. 10-21-2022
        //     - It does not respond, it just spins off until it is done, or has an exception or error, in which case, it writes it to the "severe" error logs.
        //

        var msg = 'Executing cmdNewTasksTimer2(). bwWorkflowAppId: ' + bwWorkflowAppId;
        var threatLevel = 'guarded'; // severe, high, elevated, guarded, low.
        var source = 'cmdNewTasksTimer2()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        // Get a list of all tasks where their bwHasBeenProcessedByTheWorkflowEngine == false. 
        BwWorkflowTask.find({ bwHasBeenProcessedByTheWorkflowEngine: false, bwWorkflowAppId: bwWorkflowAppId, TrashBin: { $ne: true } }, function (wtfError, wtfResult) {
            try {
                if (wtfError) {

                    var msg = 'Error in cmdNewTasksTimer2.BwWorkflowTask.find(). Database error: ' + wtfError;
                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                    var source = 'bwworkflowdataservice.js.cmdNewTasksTimer2()';
                    var errorCode = null;
                    WriteToErrorLog(threatLevel, source, errorCode, msg);

                } else {

                    // Iterate through all of the tasks and send an email.
                    if (wtfResult.length > 0) {

                        console.log('');
                        console.log('In cmdNewTasksTimer2(). Processing ' + wtfResult.length + ' New Tasks.');
                        console.log('');

                        // This means we have emails to send, so create the objects and stuff.
                        for (var i = 0; i < wtfResult.length; i++) { // This has had wrap applied, to make our loop work synchronously.

                            var promise = sendNewTaskEmailAndUpdateTask(wtfResult[i]);
                            promise.then(function (result) {
                                // Don't need to do anything here I don't think...
                                //console.log('');
                                //console.log('In CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC cmdNewTasksTimer2(). result: ' + JSON.stringify(result)); // result.length: ' + result.length);
                                //console.log('');

                            }).catch(function (e) {

                                var msg = 'Exception in cmdNewTasksTimer2():5: ' + e.message + ', ' + e.stack;
                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.cmdNewTasksTimer2()';
                                var errorCode = null;
                                WriteToErrorLog(threatLevel, source, errorCode, msg, wtfResult[i].bwWorkflowAppId, wtfResult[i].bwAssignedToId);

                            });

                        }
                    }
                }
            } catch (e) {

                var msg = 'Exception in cmdNewTasksTimer2():4: ' + e.message + ', ' + e.stack;
                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                var source = 'start.js.cmdNewTasksTimer2()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg);

            }
        });

    } catch (e) {

        var msg = 'Exception in cmdNewTasksTimer2():1: ' + e.message + ', ' + e.stack;
        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
        var source = 'start.js.cmdNewTasksTimer2()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

    }
}


