function getDueDateOneDayFromNowAsDateType(bwWorkflowTaskItemId) {
    return new Promise(function (resolve, reject) {
        try {
            console.log('In getDueDateOneDayFromNowAsDateType(). bwWorkflowTaskItemId: ' + bwWorkflowTaskItemId);

            if (bwWorkflowTaskItemId) {

                // If we get here, get the old date and add a day to it. 7-21-2022
                BwWorkflowTask.find({ bwWorkflowTaskItemId: bwWorkflowTaskItemId }, function (wtfError, wtfResult) {
                    try {
                        if (wtfError) {

                            var msg = 'Error in start.js.getDueDateOneDayFromNowAsDateType:' + wtfError;
                            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.getDueDateOneDayFromNowAsDateType()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            //var result = {
                            //    message: msg
                            //}
                            reject(msg);
                        } else {

                            if (wtfResult.length && (wtfResult.length != 1)) {

                                var msg = 'Error in getDueDateOneDayFromNowAsDateType(). Unexpected length value for BwWorkflowTask.find(). bwWorkflowTaskItemId: ' + bwWorkflowTaskItemId + ', wtfResult.length: ' + wtfResult.length;
                                reject(msg);

                            } else {

                                if (wtfResult[0].DailyOverdueTaskNotificationDate) {
                                    var dailyOverdueTaskNotificationDate = wtfResult[0].DailyOverdueTaskNotificationDate;
                                    var dueDate = dailyOverdueTaskNotificationDate.setDate(dailyOverdueTaskNotificationDate.getDate() + 1); // This adds a day.
                                    resolve(dueDate);
                                } else {
                                    //var msg = 'xcx235356464576575637 ERROR in start.js.getDueDateOneDayFromNowAsDateType. wtfResult: ' + JSON.stringify(wtfResult);
                                    //var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                    //var source = 'start.js.getDueDateOneDayFromNowAsDateType()';
                                    //var errorCode = null;
                                    //WriteToErrorLog(threatLevel, source, errorCode, msg);

                                    var now = new Date();
                                    now.setDate(now.getDate() + 1); // This adds a day.
                                    now.setHours(now.getHours()); // THIS ADJUSTMENT JUST THREW EVERYTHING OFF!!! + serverDateGMTOffsetCorrectionHours); // This is our fix for the GMT being generated.
                                    resolve(now);

                                }

                            }

                        }
                    } catch (e) {

                        var msg = 'Exception in getDueDateOneDayFromNowAsDateType():2: ' + e.message + ', ' + e.stack;
                        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                        var source = 'start.js.getDueDateOneDayFromNowAsDateType()';
                        var errorCode = null;
                        WriteToErrorLog(threatLevel, source, errorCode, msg);

                        reject(msg);

                    }
                });

            } else {

                // Regarding how new Date() returns GMT and not local time. THIS MAY NOT BE ENTIRELY TRUE.
                // From the web: This is not a bug, just a choice of how Node decides to represent a Date object in its REPL. 
                // Also, as of node v0.7.x, this output has been changed to display local time, matching the browser behavior.
                // We are using serverDateGMTOffsetCorrectionHours as our way of handling this.
                var now = new Date();
                now.setDate(now.getDate() + 1); // This adds a day.
                now.setHours(now.getHours()); // THIS ADJUSTMENT JUST THREW EVERYTHING OFF!!! + serverDateGMTOffsetCorrectionHours); // This is our fix for the GMT being generated.
                resolve(now);

            }

        } catch (e) {

            var msg = 'Exception in getDueDateOneDayFromNowAsDateType(): ' + e.message + ', ' + e.stack;
            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
            var source = 'start.js.getDueDateOneDayFromNowAsDateType()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg);
            reject(msg);

        }
    });
}




