router.get('/_bw/getstatusofworkflowtimer2', function (request, response) {
    try {
        console.log('In getstatusofworkflowtimer2().');

        BwForestConfiguration.findOne({ bwForestConfigurationId: 1 }, function (fcfError, fcfResult) {
            if (fcfError) {

                var msg = 'Error in getstatusofworkflowtimer2.BwForestConfiguration.find(): ' + fcfError;
                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                var source = 'start.js.getstatusofworkflowtimer2()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg);

                var result = {
                    status: 'ERROR',
                    message: msg
                };
                response.send(result);

            } else {

                if (!fcfResult) {

                    var bwForestConfiguration = new BwForestConfiguration({ bwForestConfigurationId: 1 });
                    bwForestConfiguration.save(function (error) {
                        if (error) {

                            var msg = 'Error in getstatusofworkflowtimer2.bwForestConfiguration.save(): ' + error;
                            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.launchTimerServices_KeepAlive()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            var result = {
                                status: 'ERROR',
                                message: msg
                            };
                            response.send(result);

                        } else {

                            var msg = 'Error in getstatusofworkflowtimer2.BwForestConfiguration.findOne(). Invalid value for fcfResult: ' + fcfResult + '. This may be a new database. The required single record here has been created. Refresh your browser window and it should now work Ok.';
                            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.getstatusofworkflowtimer2()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            var result = {
                                status: 'ERROR',
                                message: msg
                            };
                            response.send(result);

                        }
                    });

                } else {

                    BwThreadRegistry.find({}, function (trfError, trfResult) {
                        try {
                            if (trfError) {

                                var msg = 'Error in getstatusofworkflowtimer2.BwThreadRegistry.find(): ' + trfError;
                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.getstatusofworkflowtimer2()';
                                var errorCode = null;
                                WriteToErrorLog(threatLevel, source, errorCode, msg);

                                var result = {
                                    status: 'ERROR',
                                    message: msg
                                };
                                response.send(result);

                            } else {

                                var result = {
                                    status: 'SUCCESS',
                                    message: 'SUCCESS',
                                    ForestConfiguration: fcfResult,
                                    ThreadRegistry: trfResult
                                };
                                response.send(result);

                            }
                        } catch (e) {

                            var msg = 'Exception in getstatusofworkflowtimer2.BwThreadRegistry.find(): ' + e.message + ', ' + e.stack;
                            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                            var source = 'start.js.getstatusofworkflowtimer2()';
                            var errorCode = null;
                            WriteToErrorLog(threatLevel, source, errorCode, msg);

                            var result = {
                                status: 'EXCEPTION',
                                message: msg
                            };
                            response.send(result);

                        }
                    });

                }

            }

        });

    } catch (e) {

        var msg = 'Exception in getstatusofworkflowtimer2(): ' + e.message + ', ' + e.stack;
        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
        var source = 'start.js.getstatusofworkflowtimer2()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        var result = {
            status: 'EXCEPTION',
            message: msg
        };
        response.send(result);

    }
});


