router.delete('/_bw/bwtasksfindallforadminthatwillhaveemailssenttoday', function (request, response) {
    try {

        var now = new Date();
        var year = now.getFullYear();
        var month = now.getMonth() + 1;
        var day = now.getDate();
        var hour = now.getHours();
        var minutes = now.getMinutes();
        var seconds = now.getSeconds();

        var now2 = new Date(year, month, day + 2, hour, minutes, seconds, 0);

        // TODD: Can we perform this query on distinct bwWorkflowTaskItemId?? Does it matter? Update: No, it doesn't matter!

        BwWorkflowTask.find({
            bwHasBeenProcessedByTheWorkflowEngine: { $ne: false }, bwPercentComplete: 0, DailyOverdueTaskNotificationDate: {
                $lte: now2
            }, TrashBin: { $ne: true }
        }, function (error, result) {
            if (!error) {
                response.send(result);
            } else {
                response.send('Error in DELETE /bwtasksfindallforadminthatwillhaveemailssenttoday:' + error);
            }
        });
    } catch (e) {
        console.log('Exception in bwtasksfindallforadminthatwillhaveemailssenttoday(): ' + e.message + ', ' + e.stack);
        response.send('Error in DELETE /bwtasksfindallforadminthatwillhaveemailssenttoday:' + e.message);
    }
});



