router.delete('/_bw/bwwebapperrororsuggestion/:bwWorkflowAppId', function (request, response) {
    try {
        console.log('Listing all bwwebapperrororsuggestion for bwWorkflowAppId: ' + request.params.bwWorkflowAppId);

        var bwWorkflowAppId = request.params.bwWorkflowAppId;

        if (bwWorkflowAppId == 'all') {
            BwErrorOrSuggestion.find({
            }, null, {
                sort: {
                    Created: 'descending'
                }
            }, function (err, eosfResult) { // Added sort 1-20-2020
                if (err) {
                    console.log(err);
                    var results = {
                        message: err
                    }
                    response.send(results);
                } else {
                    var results = {
                        message: 'SUCCESS',
                        result: eosfResult
                    }
                    response.send(results);
                }
            });
        } else {
            BwErrorOrSuggestion.find({
                bwWorkflowAppId: bwWorkflowAppId
            }, null, {
                sort: {
                    Created: 'descending'
                }
            }, function (err, eosfResult) { // Added sort 1-20-2020
                if (err) {
                    console.log(err);
                    var results = {
                        message: err
                    }
                    response.send(results);
                } else {
                    var results = {
                        message: 'SUCCESS',
                        result: eosfResult
                    }
                    response.send(results);
                }
            });
        }
    } catch (e) {
        console.log('Exception in bwwebapperrororsuggestion(): ' + e.message + ', ' + e.stack);
        var results = {
            message: 'Exception in bwwebapperrororsuggestion(): ' + e.message + ', ' + e.stack
        }
        response.send(results);
    }
});

