router.post('/_bw/participantemail_sent', function (request, response) {
    try {
        console.log('In start.js.participantemail_sent().');

        //
        // This is the web service which is called whne a user wants to view their email.
        //

        var bwParticipantId_LoggedIn = request.body.bwParticipantId_LoggedIn;
        var bwActiveStateIdentifier = request.body.bwActiveStateIdentifier;
        var bwWorkflowAppId_LoggedIn = request.body.bwWorkflowAppId_LoggedIn;

        var promise = AuthorizeWebServiceCall(request, bwParticipantId_LoggedIn, bwActiveStateIdentifier, bwWorkflowAppId_LoggedIn, 'participant'); //'Forest Administrator');
        promise.then(function (result) {
            try {

                if (result.status == 'AUTHORIZED') {

                    // AUTHORIZED.
                    console.log('AUTHORIZED in /participantemail_sent().');
                    console.log('AUTHORIZED');
                    console.log('AUTHORIZED');

                    var bwParticipantId = bwParticipantId_LoggedIn;
                    var offset = request.body.offset;
                    var limit = request.body.limit;

                    if (!(offset && limit)) {

                        var msg = 'Error in webservices.start.js.participantemail_sent(). Unexpected values for offset: ' + offset + ', limit: ' + limit;
                        var result = {
                            status: 'ERROR',
                            message: msg
                        }

                        response.send(result);

                    } else {

                        var emailQuery;
                        //if (bwParticipantId == 'dcfbc697-7728-4e0f-8620-8d9ab6ed31c6') {

                        //    //
                        //    // This is the workflow administrator. Todd at the moment. 1-18-2024.
                        //    //
                        //    emailQuery = { $or: [{ bwParticipantId: bwParticipantId }, { bwParticipantId: null }, { bwParticipantId: '' }], TrashBin: { $ne: true } };

                        //} else {

                        // This is a participant with a single email address.
                        emailQuery = { bwParticipantId: bwParticipantId, TrashBin: { $ne: true } };

                        //}

                        //BwSentEmail.find({ TrashBin: { $ne: true } }, null, { sort: { Timestamp: 'descending' }, limit: 35 }, function (error, results) { // Added sort 10-31-2023.
                        BwSentEmail.paginate(emailQuery, { select: '_id bwEmailId TheUserHasReadThisEmail subject to from attachments timestamp ThisEmailIsFromAnInternalSource', offset: offset, limit: limit, sort: { timestamp: 'descending' } })
                            .then(function (results) {
                                try {

                                    //
                                    //
                                    // DEV: If the email body is too large, or there are attachments, we can be sending a lot fof data to the client. That is why we are sending the summary data. This will let the UI load quickly, and maybe we will back fill to the client somehow, TBD. 1-7-2024.
                                    //
                                    //

                                    //var results2 = [results[0], results[1], results[2], results[3], results[4]];

                                    var result = {
                                        status: 'SUCCESS',
                                        message: 'SUCCESS',
                                        results: results,
                                        pid: process.pid
                                    }

                                    response.send(result);

                                } catch (e) {

                                    var msg = 'Exception in start.js./participantemail_sent:3-22: ' + e.message + ', ' + e.stack;
                                    var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                    var source = 'start.js./participantemail_sent()';
                                    var errorCode = null;
                                    WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

                                    var result = {
                                        status: 'EXCEPTION',
                                        message: msg
                                    }

                                    response.send(result);

                                }

                            }).catch(function (e) {

                                var msg = 'Exception in start.js./participantemail_sent:3-22-1: ' + JSON.stringify(e);
                                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                                var source = 'start.js./participantemail_sent()';
                                var errorCode = null;
                                WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

                                var result = {
                                    status: 'EXCEPTION',
                                    message: msg
                                }

                                response.send(result);

                            });

                    }

                } else {

                    // UNAUTHORIZED.
                    console.log('UNAUTHORIZED in /participantemail_sent().');
                    console.log('UNAUTHORIZED');
                    console.log('UNAUTHORIZED');
                    response.status(401);
                    response.send(result);

                }

            } catch (e) {

                var msg = 'Exception in start.js./participantemail_sent:3: ' + e.message + ', ' + e.stack;
                var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
                var source = 'start.js./participantemail_sent()';
                var errorCode = null;
                WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

                var result = {
                    status: 'EXCEPTION',
                    message: msg
                }
                response.send(result);

            }

        }).catch(function (e) {

            var msg = 'Exception in start.js./participantemail_sent:2: ' + e;
            var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
            var source = 'start.js./participantemail_sent()';
            var errorCode = null;
            WriteToErrorLog(threatLevel, source, errorCode, msg, bwWorkflowAppId_LoggedIn);

            var result = {
                status: 'EXCEPTION',
                message: msg
            }
            response.send(result);

        });

    } catch (e) {

        var msg = 'Exception in start.js.participantemail_sent(): ' + e.message + ', ' + e.stack;
        var threatLevel = 'severe'; // severe, high, elevated, guarded, low.
        var source = 'start.js.participantemail_sent()';
        var errorCode = null;
        WriteToErrorLog(threatLevel, source, errorCode, msg);

        var result = {
            status: 'EXCEPTION',
            message: msg
        }
        response.send(result);

    }
});


