router.post('/_bw/UpdateNotifyForestAdministratorToReviewEmailsViaSms', function (request, response) {
    try {

        var ip = request.headers['x-forwarded-for'] ||
            request.connection.remoteAddress ||
            request.socket.remoteAddress ||
            (request.connection.socket ? request.connection.socket.remoteAddress : null
            );
        var ips = [];
        for (var x = 0; x < ip.split(',').length; x++) {
            if (ip.split(',')[x].trim() == '127.0.0.1') {
                // do nothing
            } else {
                // add to array
                ips.push(ip.split(',')[x].trim());
            }
        }

        console.log('In /odata/UpdateNotifyForestAdministratorToReviewEmailsViaSms: Attempt to save workflow from (' + ips + ')');

        var NotifyForestAdministratorToReviewEmailsViaSms = request.body.NotifyForestAdministratorToReviewEmailsViaSms;

        BwForestConfiguration.find({
            bwForestConfigurationId: 1
        }, {
        }, {
        }, function (fcError, fcResult) {
            try {
                if (fcError) {
                    // Exception section:
                    var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                    var source = 'start.js.UpdateNotifyForestAdministratorToReviewEmailsViaSms:1';
                    var errorCode = null;
                    var message = fcError;
                    WriteToErrorLog(threatLevel, source, errorCode, message);
                    //
                    response.send('Error in UpdateNotifyForestAdministratorToReviewEmailsViaSms.BwForestConfiguration.find:1:' + fcError);
                } else {
                    if (fcResult && fcResult[0]) {
                        // UPDATE
                        BwForestConfiguration.update({
                            bwForestConfigurationId: 1
                        }, {
                            NotifyForestAdministratorToReviewEmailsViaSms: NotifyForestAdministratorToReviewEmailsViaSms
                        }, {
                        }, function (error, mod) {
                            if (!error) {
                                var result = {
                                    message: 'SUCCESS'
                                };
                                response.send(result);
                            } else {
                                var msg = 'Error updating the post /UpdateNotifyForestAdministratorToReviewEmailsViaSms: ' + error;
                                // Exception section:
                                var threatLevel = 'high'; // severe, high, elevated, guarded, low.
                                var source = 'start.js.post.UpdateNotifyForestAdministratorToReviewEmailsViaSms()';
                                var errorCode = null;
                                var message = msg;
                                WriteToErrorLog(threatLevel, source, errorCode, message);
                                //
                                var result = {
                                    message: msg
                                };
                                response.send(result);
                            }
                        });
                    } else {
                        // SAVE
                        var bwForestConfiguration = new BwForestConfiguration({
                            bwForestConfigurationId: 1,
                            ForestAdministratorId: '',
                            ForestAdministratorEmail: '',
                            ForestAdministratorFriendlyName: '',
                            ForestAdministratorTextMessageNumber: '',
                            ForestAdministratorToReviewEmailsBeforeSending: true,
                            NotifyForestAdministratorToReviewEmailsViaSms: NotifyForestAdministratorToReviewEmailsViaSms
                        });
                        bwForestConfiguration.save(function (error) {
                            if (!error) {
                                var result = {
                                    message: 'SUCCESS'
                                };
                                response.send(result);
                            } else {
                                var result = {
                                    message: 'Error in POST UpdateNotifyForestAdministratorToReviewEmailsViaSms(): ' + error
                                };
                                response.send(result);
                            }
                        });
                    }
                }
            } catch (e) {
                console.log('Exception in UpdateNotifyForestAdministratorToReviewEmailsViaSms(). ' + e.message + ', ' + e.stack);
                var result = {
                    message: 'Exception in UpdateNotifyForestAdministratorToReviewEmailsViaSms(). ' + e.message + ', ' + e.stack
                };
                response.send(result);
            }
        });

    } catch (e) {
        // Exception section:
        var threatLevel = 'high'; // severe, high, elevated, guarded, low.
        var source = 'start.js.POST.UpdateNotifyForestAdministratorToReviewEmailsViaSms()';
        var errorCode = null;
        var message = e.message;
        WriteToErrorLog(threatLevel, source, errorCode, message);
        //
        var result = {
            message: 'Exception in POST UpdateNotifyForestAdministratorToReviewEmailsViaSms: ' + e.message + ', ' + e.stack
        };
        response.send(result);
    }
});

